import type { MeaningPack } from '../../types';

export const taSundaraVerses5: MeaningPack = {
  lang: 'ta',
  texts: {
    'sundarakanda-57': {
      verses: {
        '0.0': 'சிறகுடைய மலையைப் போல் பெருவேகத்துடன் தாவி ஹனுமான் வானமெனும் கடலைக் கடந்தான்; அதில் நாகர், யக்ஷர், கந்தர்வர் மலர்ந்த தாமரைகளும் அல்லிகளும் போல இருந்தனர்.',
        '0.1': 'அதில் சந்திரனே அழகிய வெள்ளல்லி, சூரியனே காரண்டவப் பறவை, திஷ்ய-ஶ்ரவண நட்சத்திரங்களே அன்னங்கள், மேகங்களே பாசியும் புல்லும்.',
        '0.2': 'புனர்வஸுவே அதன் பெரிய மீன், செவ்வாயே பெரும் முதலை, ஐராவதமே பெரிய தீவு, ஸ்வாதி நட்சத்திரமே உலவும் அன்னம்.',
        '0.3': 'காற்றுத் திரள்களே அதன் அலைகள், சந்திரக் கதிர்களே குளிர்ந்த நீர்; அத்தகைய வானக்கடலை ஹனுமான் களைப்பின்றித் தாவிக் கடந்தான்.',
        '0.4': 'வானத்தையே விழுங்குபவன் போலவும், சந்திரனை உரசுபவன் போலவும், நட்சத்திரங்களுடனும் சூரிய மண்டலத்துடனும் வானையே கவர்ந்து செல்பவன் போலவும் அவன் சென்றான்.',
        '0.5': 'களைப்பற்ற ஹனுமான் அந்த எல்லையற்ற வானக்கடலில் மூழ்கி, மேகக் கூட்டங்களை இழுத்துச் செல்பவன் போலச் சென்றான்.',
        '0.6': 'அங்கே வெண்மை-செம்மை, நீலம்-மஞ்சிட்டம், பச்சை-சிவப்பு நிறங்களுடைய பெரும் மேகங்கள் ஒளிர்ந்தன.',
        '0.7': 'மேகத் திரள்களுக்குள் மீண்டும் மீண்டும் நுழைந்து வெளிவந்த அவன், ஒருமுறை தெரிந்து ஒருமுறை மறையும் சந்திரனைப் போல் காணப்பட்டான்.',
        '0.8': 'பலவகை அடர்ந்த மேகங்களிடையே சென்ற, வெண்ணாடை அணிந்த அந்த வீரனின் உடல் ஒருமுறை தெரிந்தும் ஒருமுறை மறைந்தும், வானில் அவன் சந்திரனைப் போல் விளங்கினான்.',
        '0.9': 'கருடனைப் போல் வானில் பறந்து, மேகக் கூட்டங்களைக் கிழித்து மீண்டும் மீண்டும் வெளிப்பட்ட வாயுமைந்தன் ஒளிர்ந்தான்.',
        '0.10': 'இடிபோன்ற பெரும் முழக்கத்துடன் கர்ஜித்து, முதன்மையான ராக்ஷஸர்களைக் கொன்று தன் பெயரை முழங்கி,',
        '0.11': 'நகரைக் கலங்கச் செய்து, ராவணனை வருத்தி, மாவீரர்களை நசுக்கி, வைதேஹியை வணங்கி,',
        '0.12': 'அந்த மாபெரும் ஒளியுடைய வீரன் கடலின் நடுவழியாகத் திரும்பி வந்தான்; வழியில் மலையரசன் ஸுநாபனை (மைநாகனை) தொட்டுச் சென்றான்.',
        '0.13': 'வில்நாணிலிருந்து விடுபட்ட அம்பைப் போல் பெருவேகத்துடன் சென்று, சற்று அருகில் வந்ததும் அந்தப் பெருமலையைக் கண்டான்.',
        '0.14': 'மேகம் போலத் தோன்றிய மகேந்திர மலையைக் கண்டு அந்த மாகபி கர்ஜித்து, சுற்றிலும் பத்துத் திசைகளையும் நிரப்பினான்.',
        '0.15': 'இடிபோன்ற பெரும் முழக்கத்துடன் கர்ஜித்து, நண்பர்களைக் காணும் ஆவலுடன் அவன் அந்த இடத்தை அடைந்தான்.',
        '0.16': 'அவன் பெரும் முழக்கமிட்டு வாலை அசைத்தான்; கருடன் செல்லும் வழியில் அவன் மீண்டும் மீண்டும் கர்ஜிக்க,',
        '0.17': 'அந்த முழக்கத்தால் சூரிய மண்டலத்துடன் வானமே பிளப்பது போலிருந்தது. கடலின் வடகரையில் இருந்த மாவலிமையுடைய',
        '0.18': 'முன்பே அங்கு அமர்ந்து வாயுமைந்தனைக் காண ஆவலுடன் இருந்த அந்த வீரர்கள், காற்றால் தள்ளப்பட்ட பெருமேகத்தின் இடிபோன்ற ஹனுமானின் தொடைகளின் வேகத்தின் ஒலியைக் கேட்டனர்.',
        '0.19': 'மனம் வாடியிருந்த அந்தக் காட்டுவாசிகள் அனைவரும் மழைமேகத்தின் இடிமுழக்கம் போன்ற அந்த வானரத் தலைவனின் முழக்கத்தைக் கேட்டனர்.',
        '0.20': 'அவனது முழக்கத்தைக் கேட்டுச் சுற்றியிருந்த வானரர் அனைவரும் நண்பனைக் காணும் ஆவலுடன் துடித்தனர்.',
        '0.21': 'வானரரில் சிறந்த ஜாம்பவான் மகிழ்ச்சியால் உள்ளம் பூரித்து, வானரர் அனைவரையும் அழைத்து இவ்வாறு கூறினான்:',
        '0.22': '"ஹனுமான் நிச்சயமாகக் காரியத்தை நிறைவேற்றிவிட்டான், இதில் ஐயமில்லை; காரியம் கைகூடாவிட்டால் அவன் முழக்கம் இப்படி இருக்காது."',
        '0.23': 'அந்த மகாத்மாவின் புஜங்கள், தொடைகளின் வேகத்தையும் முழக்கத்தையும் கேட்டு வானரர் மகிழ்ந்து அங்குமிங்கும் துள்ளிக் குதித்தனர்.',
        '0.24': 'ஹனுமானைக் காணும் ஆவலுடன் அவர்கள் மகிழ்ந்து மரநுனியிலிருந்து மரநுனிக்கும், சிகரத்திலிருந்து சிகரத்திற்கும் தாவினர்.',
        '0.25': 'மகிழ்ந்த வானரர் மர நுனிகளில் கிளைகளைப் பற்றிக்கொண்டு நின்று ஒளிரும் ஆடைகளை வீசி அசைத்தனர்.',
        '0.26': 'மலைக்குகையில் சிக்கிய காற்று முழங்குவது போல் வலிமைமிக்க வாயுமைந்தன் ஹனுமான் கர்ஜித்தான்.',
        '0.27': 'அடர்மேகம் போல் இறங்கி வந்த அந்த மாகபியைக் கண்டு வானரர் அனைவரும் கைகூப்பி நின்றனர்.',
        '0.28': 'அப்போது மலைபோன்ற அந்த வேகமிக்க வீரக் கபி மரங்கள் நிறைந்த அம்மலையின் சிகரத்தில் இறங்கினான்.',
        '0.29': 'மகிழ்ச்சி நிறைந்த அவன், அழகிய மலை அருவியின் அருகே, சிறகு வெட்டப்பட்ட மலை வானிலிருந்து விழுவது போல் இறங்கினான்.',
        '0.30': 'அப்போது மனம் மகிழ்ந்த அந்தச் சிறந்த வானரர் அனைவரும் மகாத்மா ஹனுமானைச் சூழ்ந்து நின்றனர்.',
        '0.31': 'அவனைச் சூழ்ந்து, பேரானந்தம் அடைந்து, மலர்ந்த முகங்களுடன் அனைவரும் திரும்பி வந்த அவனை அணுகினர்.',
        '0.32': 'கிழங்குகளையும் கனிகளையும் காணிக்கையாகக் கொண்டுவந்து வானரர் வானரரில் சிறந்த வாயுமைந்தனைப் போற்றினர்.',
        '0.33': 'சிலர் மகிழ்ந்து முழங்கினர், சிலர் கிலகிலவென ஒலியெழுப்பினர்; மகிழ்ந்த வானரர் மரக்கிளைகளைக் கொண்டு வந்தனர்.',
        '0.34': 'அப்போது மாகபி ஹனுமான் ஜாம்பவான் முதலிய முதியோர்களையும் இளவரசன் அங்கதனையும் வணங்கினான்.',
        '0.35': 'அந்த இருவராலும் போற்றப்பட்டு, வானரர்களால் மகிழ்விக்கப்பட்ட, வணக்கத்திற்குரிய அந்த வீரன் "தேவியைக் கண்டேன்" எனச் சுருக்கமாகத் தெரிவித்தான்.',
        '0.36': 'வாலியின் மகனின் கையைப் பற்றிக்கொண்டு அவன் மகேந்திர மலையின் அழகிய வனப்பகுதியில் அமர்ந்தான்.',
        '0.37': 'கேட்கப்பட்டதும் ஹனுமான் அந்தச் சிறந்த வானரர்களிடம் கூறினான்: "அசோகவனத்தில் இருக்கும் ஜனகனின் மகளைக் கண்டேன்;',
        '0.38': 'கொடிய ராக்ஷஸிகளால் காவல் காக்கப்படும், குற்றமற்ற, ஒற்றைச் சடை தரித்த அந்த இளம்பெண் ராமனைக் காண ஏங்குகிறாள்;',
        '0.39': 'உண்ணாநோன்பால் சோர்ந்து, அழுக்கடைந்து, சடைபிடித்த கூந்தலுடன், மெலிந்திருக்கிறாள்." அப்போது வாயுமைந்தனிடமிருந்து "கண்டேன்" என்ற மகத்தான அமுதம் போன்ற சொல்லைக் கேட்டு,',
        '0.40': 'வானரர் அனைவரும் மகிழ்ந்தனர்; சில மாவலியோர் சிம்மநாதம் செய்தனர், சிலர் கூச்சலிட்டனர், சிலர் கர்ஜித்தனர்.',
        '0.41': 'சிலர் கிலகிலவென ஒலித்தனர், வேறு சிலர் எதிர்முழக்கம் செய்தனர்; மகிழ்ந்த சில சிறந்த கபிகள் வால்களை உயர்த்தினர்.',
        '0.42': 'நீண்ட, வளைந்த, நீட்டிய தங்கள் வால்களைச் சுழற்றினர்; வேறு சிலர் சிறப்புமிக்க வானரோத்தமன் ஹனுமானை',
        '0.43': 'மலைச்சிகரங்களிலிருந்து தாவி வந்து மகிழ்ச்சியுடன் தொட்டனர். சொல்லி முடித்த ஹனுமானிடம் அப்போது அங்கதன் கூறினான்,',
        '0.44': 'எல்லா வானர வீரர்களுக்கும் நடுவில் இந்தச் சிறந்த சொல்லை: "வானரனே, வலிமையிலும் வீரத்திலும் உனக்கு நிகர் யாருமில்லை,',
        '0.45': 'ஏனெனில் நீ பரந்த கடலைத் தாண்டி மீண்டும் திரும்பி வந்துள்ளாய். வானரோத்தமனே, எங்களுக்கு உயிர் தந்தவன் நீ ஒருவனே.',
        '0.46': 'உன் அருளால் நாங்கள் காரியம் கைகூடியவர்களாக ராகவனைச் சேர்வோம். ஆஹா, தலைவனிடம் உன் பக்தி! ஆஹா வீரம்! ஆஹா மனஉறுதி!',
        '0.47': 'நல்லவேளையாக நீ புகழ்மிக்க ராமபத்தினியான தேவியைக் கண்டாய்; நல்லவேளையாக காகுத்ஸ்தன் சீதையைப் பிரிந்த துயரத்தை விடுவான்."',
        '0.48': 'அப்போது வானரர் பெருமகிழ்ச்சியுடன் அங்கதன், ஹனுமான், ஜாம்பவான் ஆகியோரைச் சூழ்ந்து அகன்ற பாறைகளின் மேல் அமர்ந்தனர்.',
        '0.49': 'அம்மலையின் அகன்ற பாறைகளில் அமர்ந்த அந்தச் சிறந்த வானரர் கடல் தாண்டிய வரலாற்றைக் கேட்க விரும்பினர்,',
        '0.50': 'லங்கை, சீதை, ராவணன் ஆகியோரைக் கண்டதைப் பற்றியும் கேட்க; அனைவரும் கைகூப்பி ஹனுமானின் முகத்தையே நோக்கி அமர்ந்திருந்தனர்.',
        '0.51': 'சுவர்க்கத்தில் தேவர்களால் சேவிக்கப்படும் தேவேந்திரனைப் போல், சிறப்புமிக்க அங்கதன் பல வானரர் சூழ அங்கே அமர்ந்திருந்தான்.',
        '0.52': 'புகழ்மிக்க ஹனுமானும், தோள்களில் தோள்வளைகள் அணிந்த அங்கதனும் மகிழ்ச்சியுடன் அமர்ந்திருந்த அந்த உயர்ந்த பெருமலைச் சிகரம் பேரொளியுடன் விளங்கியது.',
        '0.53': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் ஐம்பத்தேழாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sundarakanda-58': {
      verses: {
        '0.0': 'பின்னர் மகேந்திர மலைச் சிகரத்தில் ஹனுமான் முதலான மாவலிமையுடைய வானரர் பேரானந்தம் அடைந்தனர்.',
        '0.1': 'மகாத்மாக்களான வானரர் மகிழ்ச்சியுடன் அமர்ந்ததும், மகிழ்ந்த ஜாம்பவான் மகிழ்ச்சியுடனிருந்த அந்த மாகபியிடம்',
        '0.2': 'அந்த வாயுமைந்தனிடம் காரிய வரலாற்றைக் கேட்டான்: "தேவியை நீ எப்படிக் கண்டாய்? அவள் அங்கே எவ்வாறு இருக்கிறாள்?',
        '0.3': 'கொடுஞ்செயலனான பத்துத்தலையன் அவளிடம் எப்படி நடந்துகொள்கிறான்? மாகபியே, இவை அனைத்தையும் உள்ளபடி எங்களுக்குச் சொல்.',
        '0.4': 'தேவியை எப்படித் தேடிக் கண்டாய்? அவள் என்ன பதில் சொன்னாள்? அதைக் கேட்டு மேற்கொண்டு செய்ய வேண்டியதை மீண்டும் தீர்மானிப்போம்.',
        '0.5': 'அறிவுடையவனே, அங்கு சென்றதும் நாம் எதைச் சொல்ல வேண்டும், எதை மறைத்து வைக்க வேண்டும் என்பதை எங்களுக்கு விளக்கு."',
        '0.6': 'அவன் இவ்வாறு கேட்க, ஹனுமான் மகிழ்ச்சியால் மயிர்சிலிர்த்து, சீதாதேவியைத் தலைதாழ்த்தி வணங்கிப் பதில் கூறினான்:',
        '0.7': '"உங்கள் கண்முன்னேயே நான் மகேந்திரத்தின் உச்சியிலிருந்து வானில் தாவினேன்; கடலின் தென்கரையை அடைய வேண்டும் என்று ஒருமுகப்பட்டிருந்தேன்.',
        '0.8': 'நான் செல்லும்போது தடைபோன்ற பயங்கரமான ஒன்று தோன்றியது; மிக அழகிய தெய்வீகப் பொற்சிகரத்தைக் கண்டேன்.',
        '0.9': 'அது என் வழியை மறித்து நின்றது; அந்த மலையைத் தடையென்று கருதினேன். அந்தத் தெய்வீகச் சிறந்த பொன்மலையை அணுகி,',
        '0.10': '\'இதை நான் உடைக்க வேண்டும்\' என்று மனதில் தீர்மானித்தேன். என் வாலால் அந்தப் பெருமலையை அடித்தபோது,',
        '0.11': 'சூரியனைப் போல் ஒளிரும் அதன் சிகரம் ஆயிரம் துண்டுகளாகச் சிதறியது. என் தீர்மானத்தை அறிந்து அந்தப் பெருமலை கூறியது,',
        '0.12': 'மனதை மகிழ்விப்பது போல் \'மகனே\' என்று இனிமையாக அழைத்து: \'என்னை உன் சிற்றப்பன், வாயுவின் நண்பன் என்று அறி;',
        '0.13': 'மைநாகன் எனப் புகழ்பெற்று பெருங்கடலில் வசிப்பவன். மகனே, முன்பு சிறந்த மலைகளுக்குச் சிறகுகள் இருந்தன;',
        '0.14': 'அவை விருப்பப்படி பூமியில் திரிந்து எங்கும் துன்புறுத்தின. மலைகளின் இச்செயலைக் கேட்டு பாகசாசனனான மகேந்திரன்',
        '0.15': 'பகவானான அவன் வஜ்ராயுதத்தால் ஆயிரக்கணக்கான மலைகளின் சிறகுகளை வெட்டினான். ஆனால் உன் மகாத்மாவான தந்தை என்னை அதிலிருந்து காப்பாற்றினான்;',
        '0.16': 'குழந்தாய், அப்போது வாயு என்னை வருணனின் இருப்பிடமான கடலில் வீசினான். பகைவரை அடக்குபவனே, நான் ராகவனுக்கு உதவ வேண்டும்.',
        '0.17': 'ராமன் அறத்தைக் காப்போரில் சிறந்தவன், மகேந்திரனுக்கு நிகரான வீரன்.\' மகாத்மாவான அந்த மைநாகனிடமிருந்து இதைக் கேட்டு,',
        '0.18': 'அந்த மலைக்கு என் காரியத்தைத் தெரிவித்தேன்; என் மனம் மேலே செல்ல ஆவலுற்றது. அப்போது மகாத்மாவான மைநாகன் எனக்கு விடை தந்தான்.',
        '0.19': 'அந்தப் பெருமலை தன் மனித உருவுடனும் மலை உருவுடனும் பெருங்கடலில் மறைந்தது.',
        '0.20': 'சிறந்த வேகத்தைக் கொண்டு மீதி வழியில் புறப்பட்டேன்; பின்னர் நீண்ட நேரம் வேகமாக வழியில் சென்றேன்.',
        '0.21': 'அப்போது நாகங்களின் தாயான ஸுரஸா தேவியைக் கண்டேன்; கடலின் நடுவே அந்தத் தேவி என்னிடம் இவ்வாறு கூறினாள்:',
        '0.22': '\'வானரரில் சிறந்தவனே, தேவர்கள் உன்னை எனக்கு உணவாக நியமித்துள்ளனர்; ஆகவே உன்னை உண்பேன், தேவர்கள் உன்னை எனக்கென விதித்துள்ளனர்.\'',
        '0.23': 'ஸுரஸா இவ்வாறு கூற, நான் கைகூப்பித் தலைவணங்கி நின்று, முகம் வெளிறி இச்சொல்லைச் சொன்னேன்:',
        '0.24': '\'பகைவரை வாட்டும் சிறப்புமிக்க தசரதன் மைந்தன் ராமன், தம்பி லக்ஷ்மணனுடனும் சீதையுடனும் தண்டகாரண்யம் புகுந்தான்.',
        '0.25': 'அவன் மனைவி சீதையைத் தீயவனான ராவணன் கவர்ந்து சென்றான். ராமனின் ஆணைப்படி நான் தூதனாக அவளிடம் செல்கிறேன்.',
        '0.26': 'நல்லவளே, அவனது நாட்டில் வாழும் நீ ராமனுக்கு உதவ வேண்டும். அல்லது மைதிலியையும் அயராது செயல்புரியும் ராமனையும் கண்ட பின்',
        '0.27': 'உன் வாய்க்குள் வருவேன்; இது உண்மை, உனக்கு வாக்களிக்கிறேன்.\' நான் இவ்வாறு கூற, விரும்பிய உருவெடுக்கும் அந்த ஸுரஸா',
        '0.28': '\'யாரும் என்னைக் கடந்து செல்ல முடியாது; இது எனக்குள்ள வரம்\' என்றாள். ஸுரஸா இவ்வாறு கூற, நான் பத்து யோஜனை நீளமாக வளர்ந்தேன்,',
        '0.29': 'நொடியில் அதைவிட ஒன்றரை மடங்கு பெரியவனானேன்; அவளும் என் அளவைவிடப் பெரிதாக வாயைத் திறந்தாள்.',
        '0.30': 'திறந்த அந்த வாயைக் கண்டு நான் மீண்டும் சிறியவனானேன்; அதே கணத்தில் கட்டைவிரல் அளவாக ஆனேன்.',
        '0.31': 'விரைவாக அவள் வாய்க்குள் புகுந்து நொடியில் வெளியே வந்தேன். அப்போது ஸுரஸா தேவி தன் சொந்த உருவில் என்னிடம் கூறினாள்:',
        '0.32': '\'வானரரில் சிறந்தவனே, சாந்தமானவனே, காரியம் கைகூட மகிழ்வுடன் செல்; வைதேஹியை மகாத்மாவான ராகவனுடன் சேர்த்து வை.',
        '0.33': 'வலிய கரங்களுடைய வானரனே, மகிழ்ந்திரு; உன்னால் நான் மகிழ்ந்தேன்.\' அப்போது எல்லா உயிர்களும் \'நன்று, நன்று\' என்று என்னைப் புகழ்ந்தன.',
        '0.34': 'பின்னர் கருடனைப் போல் பரந்த வானில் பறந்தேன்; அப்போது என் நிழல் பற்றப்பட்டது, ஆனால் எனக்கு எதுவும் தெரியவில்லை.',
        '0.35': 'வேகம் தடைபட்ட நான் பத்துத் திசைகளையும் பார்த்தேன்; ஆனால் என் செலவைத் தடுத்தது எதுவும் அங்கே தெரியவில்லை.',
        '0.36': 'அப்போது எனக்கு இந்த எண்ணம் தோன்றியது: \'என் பயணத்தில் இது என்ன தடை? இங்கே எந்த உருவமும் தெரியவில்லையே!\'',
        '0.37': 'சிந்தித்துக்கொண்டிருந்த என் பார்வை அப்போது கீழே விழுந்தது; அங்கே நீரில் கிடந்த கொடிய ராக்ஷஸியைக் கண்டேன்.',
        '0.38': 'அந்தக் கொடியவள் உரக்கச் சிரித்து, பதறாமல் நின்ற என்னிடம் இந்த அமங்கலமான சொல்லைச் சொன்னாள்:',
        '0.39': '\'பேருடலனே, எங்கே செல்கிறாய்? பசியோடிருக்கும் எனக்கு நீ விரும்பிய உணவு. நீண்ட நாளாக உணவில்லாத என் உடலைத் திருப்திப்படுத்து.\'',
        '0.40': '\'சரி\' என்று அவள் சொல்லை ஏற்று, அவள் வாயின் அளவைவிடப் பெரிதாக என் உடலைப் பெருக்கினேன்.',
        '0.41': 'என்னை உண்ண அவளது பெரிய கொடிய வாயும் வளர்ந்தது; ஆனால் அவள் என்னையோ நான் செய்த உருமாற்றத்தையோ அறியவில்லை.',
        '0.42': 'அப்போது இமைப்பொழுதில் என் பெரிய உருவைச் சுருக்கி, அவள் இதயத்தைப் பிடுங்கிக்கொண்டு வானில் பறந்தேன்.',
        '0.43': 'என்னால் இதயம் பிடுங்கப்பட்ட மலைபோன்ற அந்தக் கொடியவள் கைகளை விரித்தபடி உப்புக்கடலில் விழுந்தாள்.',
        '0.44': 'வானில் உலவும் மகாத்மாக்களின் இனிய சொற்களைக் கேட்டேன்: \'கொடிய ராக்ஷஸி ஸிம்ஹிகையை ஹனுமான் விரைவில் கொன்றான்.\'',
        '0.45': 'அவளைக் கொன்று, அவசரமான காரியத்தை நினைத்து மேலே சென்றேன்; நீண்ட தொலைவைக் கடந்து மலைகளால் அழகுபெற்ற',
        '0.46': 'லங்காபுரி இருக்கும் கடலின் தென்கரையைக் கண்டேன். சூரியன் மறைந்ததும் ராக்ஷஸர்களின் இருப்பிடமான அந்நகரில்',
        '0.47': 'கொடிய வீரமுடைய ராக்ஷஸர்கள் அறியாதபடி நுழைந்தேன். நான் நுழையும்போது ஊழிக்கால மேகம் போல் ஒளிர்ந்த',
        '0.48': 'ஒரு பெண் அட்டகாசமாகச் சிரித்தபடி என் முன் எழுந்து நின்றாள். எரியும் நெருப்புப் போன்ற கூந்தலுடன், என்னைக் கொல்ல விரும்பிய',
        '0.49': 'அந்தப் பெரும் கொடியவளை இடக்கை முஷ்டியால் அடித்து வென்று, அந்திவேளையில் உள்ளே நுழைந்தேன். அஞ்சிய அவள் என்னிடம் சொன்னாள்:',
        '0.50': '\'வீரனே, நான் லங்காபுரி; உன் வீரத்தால் வெல்லப்பட்டேன். ஆகவே நீ எல்லா ராக்ஷஸர்களையும் முழுமையாக வெல்வாய்.\'',
        '0.51': 'அங்கே இரவு முழுதும் ஜனகனின் மகளைத் தேடித் திரிந்தேன்; ராவணனின் அந்தப்புரத்திலும் நுழைந்தேன், ஆனால் அந்த அழகியைக் காணவில்லை.',
        '0.52': 'ராவணனின் மாளிகையில் சீதையைக் காணாமல் நான் துயரக் கடலில் மூழ்கினேன்; அதன் கரையே எனக்குத் தெரியவில்லை.',
        '0.53': 'துயருற்றிருந்த நான் உயர்ந்த பொன் மதிலால் சூழப்பட்ட சிறந்த அரண்மனைத் தோட்டத்தைக் கண்டேன்.',
        '0.54': 'மதிலைத் தாண்டிக் குதித்து பல மரங்கள் நிறைந்த அதைக் கண்டேன்; அசோகவனத்தின் நடுவே ஒரு பெரிய சிம்சுபா மரம் இருந்தது.',
        '0.55': 'அதில் ஏறிப் பார்த்தபோது பொன்னிற வாழைத்தோப்பைக் கண்டேன்; சிம்சுபா மரத்திலிருந்து சற்றுத் தொலைவில் அந்த அழகியைக் கண்டேன்;',
        '0.56': 'கருநிறத்தவள், தாமரையிதழ்க் கண்ணாள், உண்ணாநோன்பால் மெலிந்த முகத்தவள், அந்த ஒரே ஆடையைச் சுற்றியவள், புழுதியடைந்த கூந்தலுடையவள்;',
        '0.57': 'துயரத்தாலும் வேதனையாலும் வாடிய அங்கங்களுடைய, கணவனின் நலனிலேயே நிலைத்த சீதையைக் கண்டேன்; அவள் விகாரமான கொடிய ராக்ஷஸிகளால் சூழப்பட்டிருந்தாள்,',
        '0.58': 'இறைச்சியும் இரத்தமும் உண்ணும் புலிகளிடையே மான் போல. ராக்ஷஸிகளிடையே மீண்டும் மீண்டும் அச்சுறுத்தப்பட்டுக்கொண்டிருந்த அவளைக் கண்டேன்;',
        '0.59': 'ஒற்றைச் சடை தரித்த, துயருற்ற, கணவனைப் பற்றிய சிந்தனையிலேயே மூழ்கிய, தரையில் படுக்கும், பனிக்காலம் வந்தபோது தாமரைக்கொடி போல் ஒளியிழந்த அவளை.',
        '0.60': 'அவள் ராவணனிடமிருந்து மனதைத் திருப்பி இறக்கத் தீர்மானித்திருந்தாள். மான்குட்டி போன்ற கண்களுடைய அவளை நான் எப்படியோ விரைவில் அடைந்தேன்.',
        '0.61': 'அத்தகைய நிலையில் இருந்த புகழ்மிக்க ராமபத்தினியைக் கண்டு நான் அதே சிம்சுபா மரத்தில் பார்த்தபடி இருந்தேன்.',
        '0.62': 'அப்போது ராவணனின் மாளிகையில் ஒட்டியாணம், சிலம்புகளின் ஒலியுடன் கலந்த மிக ஆழ்ந்த ஆரவாரத்தைக் கேட்டேன்.',
        '0.63': 'மிகவும் பதற்றமடைந்த நான் என் உருவைச் சுருக்கிக்கொண்டு அடர்ந்த இலைகளில் பறவை போல் சிம்சுபா மரத்தில் மறைந்திருந்தேன்.',
        '0.64': 'அப்போது ராவணனின் மனைவியரும் மாவலியோனான ராவணனும் சீதை இருந்த அந்த இடத்திற்கு வந்தனர்.',
        '0.65': 'ராக்ஷஸ அரசனைக் கண்டு அழகி சீதை தொடைகளைக் குறுக்கிக்கொண்டு கைகளால் மார்பை மறைத்துக்கொண்டாள்.',
        '0.66': 'அவள் அஞ்சி மிகவும் கலங்கி அங்குமிங்கும் பார்த்தாள்; காப்பவர் யாரும் தெரியாமல் அந்தப் பரிதாபமான தபஸ்வினி நடுங்கினாள்.',
        '0.67': 'மிகவும் துயருற்ற அந்தச் சீதையின் முன் பத்துக்கழுத்தன் தலைகவிழ்ந்து விழுந்து, "என்னை மதித்து ஏற்றுக்கொள்" என்றான்.',
        '0.68': '"செருக்குடையவளே, ஆணவத்தால் நீ என்னை ஏற்காவிட்டால், சீதையே, இரண்டு மாதங்களுக்குப் பின் உன் இரத்தத்தைக் குடிப்பேன்."',
        '0.69': 'தீயவனான அந்த ராவணனின் இச்சொல்லைக் கேட்டு சீதை கடுஞ்சினத்துடன் இந்தச் சிறந்த சொல்லைக் கூறினாள்:',
        '0.70': '"இழிந்த ராக்ஷஸனே! நான் அளவற்ற ஒளியுடைய, இக்ஷ்வாகு குலத் தலைவனான ராமனின் மனைவி, தசரதனின் மருமகள்.',
        '0.71': 'சொல்லக்கூடாததைச் சொல்லும் உன் நாக்கு எப்படி அறுந்து விழவில்லை? இழிந்தவனே, என் கணவன் அருகில் இல்லாதபோது',
        '0.72': 'என்னைக் கவர்ந்து, அந்த மகாத்மாவின் கண்ணில் படாமல் ஓடி வந்த பாவியே, உன் வீரம் என்ன? நீ ராமனுக்கு நிகரல்ல; அவனுக்கு அடிமையாகவும் தகுதியற்றவன்.',
        '0.73': 'ராகவன் வெல்லமுடியாதவன், சத்தியம் பேசுபவன், வீரன், போரில் பெருமை கொள்பவன்." ஜானகியின் இத்தகைய கடுஞ்சொற்களைக் கேட்ட பத்துத்தலையன்',
        '0.74': 'சிதையின் மேல் எரியும் நெருப்பைப் போல் சினத்தால் திடீரெனக் கொழுந்துவிட்டான்; கொடிய கண்களை உருட்டி வலக்கை முஷ்டியை உயர்த்தி,',
        '0.75': 'மைதிலியைக் கொல்லத் தொடங்கினான்; அப்போது பெண்கள் ஐயோ என அலறினர். பெண்களிடையிருந்து அந்தத் தீயவனின் மனைவி முன்னே பாய்ந்தாள்,',
        '0.76': 'சிறந்தவளான மண்டோதரி என்பவள் அவனைத் தடுத்தாள். காமத்தால் வாடிய அவனிடம் அவள் இனிமையாகக் கூறினாள்:',
        '0.77': '"மகேந்திரனுக்கு நிகரான வீரனே, சீதையால் உனக்கு என்ன ஆக வேண்டும்? இன்று என்னுடன் இன்புறு; ஜானகி என்னைவிடச் சிறந்தவளல்ல.',
        '0.78': 'பிரபுவே, தேவ, கந்தர்வ கன்னியருடனும் யக்ஷ கன்னியருடனும் இன்புறு; சீதையால் என்ன செய்வாய்?"',
        '0.79': 'பின்னர் ஒன்றுகூடிய அப்பெண்கள் மாவலியோனான அந்த இரவுலாவியை உடனே எழுப்பி அவனது மாளிகைக்கு அழைத்துச் சென்றனர்.',
        '0.80': 'பத்துக்கழுத்தன் சென்றபின், விகார முகமுடைய ராக்ஷஸிகள் கொடிய, மிகப் பயங்கரமான சொற்களால் சீதையை மிரட்டினர்.',
        '0.81': 'ஜானகி அவர்களின் பேச்சைத் துரும்பாகக் கருதினாள்; சீதையிடம் அவர்களின் கர்ஜனையும் பயனற்றுப் போனது.',
        '0.82': 'வீணாகக் கர்ஜித்துச் செய்வதறியாத இறைச்சியுண்ணும் ராக்ஷஸிகள் சீதையின் உறுதியான தீர்மானத்தை ராவணனிடம் தெரிவித்தனர்.',
        '0.83': 'பின்னர் அவர்கள் அனைவரும் நம்பிக்கை இழந்து, முயற்சியைக் கைவிட்டு, அவளைத் துன்புறுத்திச் சோர்ந்து உறக்கத்தில் ஆழ்ந்தனர்.',
        '0.84': 'அவர்கள் உறங்கியபோது, கணவனின் நலனில் ஈடுபட்ட சீதை பரிதாபமாகப் புலம்பி மிகுந்த துயரத்துடன் வருந்தினாள்.',
        '0.85': 'அவர்களிடையிருந்து எழுந்து த்ரிஜடை கூறினாள்: "வேண்டுமானால் உங்களையே விரைவில் தின்றுகொள்ளுங்கள்; கருவிழிச் சீதையை அல்ல,',
        '0.86': 'ஜனகனின் மகளும் தசரதனின் மருமகளுமான அந்தக் கற்புடையவளை அல்ல. ஏனெனில் இன்று நான் மயிர்க்கூச்செறியச் செய்யும் கொடிய கனவைக் கண்டேன்;',
        '0.87': 'அது ராக்ஷஸர்களின் அழிவையும் இவள் கணவனின் வெற்றியையும் குறிக்கிறது. ராகவனிடமிருந்து ராக்ஷஸிகளான நம்மைக் காக்க இவள் வல்லவள்.',
        '0.88': 'வைதேஹியிடம் இரந்து வேண்டுவோம்; இதுவே எனக்குச் சரியெனப்படுகிறது. துயருற்றவளைப் பற்றி இத்தகைய கனவு காணப்பட்டால்,',
        '0.89': 'அவள் பலவகைத் துன்பங்களிலிருந்து விடுபட்டு மேலான இன்பம் அடைவாள். ஜனகனின் மகளான மைதிலி வணக்கத்தாலேயே மனமிரங்குபவள்;',
        '0.90': 'ராக்ஷஸிகளே, பெரும் அச்சத்திலிருந்து உங்களைக் காக்க இவள் வல்லவள்." அப்போது நாணமுடைய அந்த இளம்பெண் கணவனின் வெற்றிச் செய்தியால் மகிழ்ந்து,',
        '0.91': '"அது உண்மையானால் நான் உங்களுக்கு அடைக்கலமாவேன்" என்றாள். சீதையின் அத்தகைய கொடிய நிலையைக் கண்டு,',
        '0.92': 'நான் சிறிது நேரம் சிந்தித்தேன்; ஆனால் என் மனம் அமைதி பெறவில்லை. ஜானகியுடன் பேச ஒரு வழியை யோசித்தேன்:',
        '0.93': 'முதலில் இக்ஷ்வாகு குல வம்சத்தைப் புகழ்ந்தேன். ராஜரிஷிகளின் பெயர்களால் அணிசெய்யப்பட்ட என் சொல்லைக் கேட்டு,',
        '0.94': 'கண்ணீரால் மறைந்த கண்களுடன் தேவி எனக்குப் பதில் சொன்னாள்: "வானரரில் சிறந்தவனே, நீ யார்? யார் அனுப்பினார்? இங்கு எப்படி வந்தாய்?',
        '0.95': 'ராமனுடன் உனக்கு என்ன நட்பு? அதை எனக்குச் சொல்." அவளது சொல்லைக் கேட்டு நானும் பதில் சொன்னேன்:',
        '0.96': '"தேவியே, உன் கணவன் ராமனுக்குக் கொடிய வீரமுடைய ஒரு துணைவன் இருக்கிறான்; அவன் வீரனும் மாவலியோனுமான வானர அரசன் ஸுக்ரீவன்.',
        '0.97': 'என்னை அவனுடைய சேவகன் ஹனுமான் என்று அறி; அயராது செயல்புரியும் உன் கணவன் ராமனால் உன்னிடம் அனுப்பப்பட்டு இங்கு வந்துள்ளேன்.',
        '0.98': 'புகழ்மிக்கவளே, ஆண்களில் புலியான சிறப்புமிக்க தசரதன் மைந்தன் தானே இந்த மோதிரத்தை உனக்கு அடையாளமாகக் கொடுத்துள்ளான்."',
        '0.99': '"ஆகவே தேவியே, உன் கட்டளையை விரும்புகிறேன்: நான் என்ன செய்யட்டும்? உன்னை ராம லக்ஷ்மணரிடம் அழைத்துச் செல்லட்டுமா? உன் பதில் என்ன?"',
        '0.100': 'இதைக் கேட்டுப் புரிந்துகொண்ட ஜனகனின் மகள் சீதை, "ராகவனே ராவணனை வேரோடு அழித்து என்னை அழைத்துச் செல்லட்டும்" என்றாள்.',
        '0.101': 'மேன்மையானவளும் குற்றமற்றவளுமான தேவியைத் தலைதாழ்த்தி வணங்கி, ராகவனின் மனதை மகிழ்விக்கும் அடையாளத்தை வேண்டினேன்.',
        '0.102': 'அப்போது சீதை என்னிடம் சொன்னாள்: "இந்தச் சிறந்த மணியை எடுத்துக்கொள்; இதனால் வலிய கரங்களுடைய ராமன் உன்னைப் பெரிதும் மதிப்பான்."',
        '0.103': 'இவ்வாறு சொல்லி மிகவும் கலங்கிய அந்த அழகி அந்தச் சிறந்த மணியை என்னிடம் கொடுத்து வாய்மொழியாகவும் செய்தி சொன்னாள்.',
        '0.104': 'பின்னர் ஒருமுகப்பட்ட மனத்துடன் அந்த இளவரசியை வணங்கி வலம் வந்தேன்; என் மனம் இங்கு வரத் துடித்தது.',
        '0.105': 'அப்போது அவள் மனதில் தீர்மானித்து மீண்டும் பதிலாகக் கூறினாள்: "ஹனுமானே, என் நிலையை ராகவனிடம் சொல்;',
        '0.106': 'அதைக் கேட்டவுடனே வீரர்களான ராம லக்ஷ்மணர் இருவரும் ஸுக்ரீவனுடன் தாமதமின்றி இங்கு வரும்படி செய்.',
        '0.107': 'அவ்வாறு நடக்காவிட்டால் என் வாழ்வு இன்னும் இரண்டு மாதமே; காகுத்ஸ்தன் என்னைக் காணமாட்டான், நான் ஆதரவற்றவள் போல் இறப்பேன்."',
        '0.108': 'அந்த இரக்கமான சொல்லைக் கேட்டு எனக்குச் சினம் பொங்கியது; அடுத்து செய்ய வேண்டிய மீதிக் காரியத்தை நான் தீர்மானித்தேன்.',
        '0.109': 'அப்போது என் உடல் மலையளவு வளர்ந்தது; போரை விரும்பி நான் அவனது வனத்தை அழிக்கத் தொடங்கினேன்.',
        '0.110': 'விழித்தெழுந்த விகார முகமுடைய ராக்ஷஸிகள், விலங்குகளும் பறவைகளும் அஞ்சிக் கலங்கியிருந்த அந்த அழிந்த வனப்பகுதியைப் பார்த்தனர்.',
        '0.111': 'அந்த வனத்தில் என்னைக் கண்டு அவர்கள் அங்குமிங்குமிருந்து ஒன்றுகூடி விரைந்து சென்று ராவணனிடம் சொன்னார்கள்:',
        '0.112': '"மாவலியோனான அரசே, உன் வலிமையை அறியாத ஒரு தீய வானரன் உன்னுடைய இந்த அணுகமுடியாத வனத்தை அழித்துவிட்டான்.',
        '0.113': 'அரசே, உனக்குத் தீங்கு செய்த அவனது மூடத்தனம் இத்தகையது; அவன் மீண்டும் தப்பிச் செல்லாதபடி விரைவில் அவனைக் கொல்ல ஆணையிடு."',
        '0.114': 'இதைக் கேட்டு ராக்ஷஸ அரசன், ராவணனின் விருப்பப்படி நடக்கும், வெல்வதற்கு மிகக் கடினமான கிங்கரர் எனும் ராக்ஷஸர்களை அனுப்பினான்.',
        '0.115': 'சூலங்களையும் உலக்கைகளையும் ஏந்திய அவர்களில் எண்பதாயிரம் பேரை நான் அந்த வனப்பகுதியிலேயே இரும்புத் தண்டால் கொன்றேன்.',
        '0.116': 'மடிந்தோர் போக எஞ்சியவர்கள் விரைந்து ஓடி, நான் சேனையை அழித்ததை ராவணனிடம் தெரிவித்தனர்.',
        '0.117': 'அப்போது எனக்குச் சிறந்த சைத்ய மாளிகை பற்றிய எண்ணம் தோன்றியது; அங்கிருந்த நூறு ராக்ஷஸர்களைத் தூணால் கொன்று,',
        '0.118': 'லங்கையின் அணிகலன் போன்ற அதைச் சினத்துடன் தகர்த்தேன். அப்போது ராவணன் பிரஹஸ்தனின் மகன் ஜம்புமாலிக்கு ஆணையிட்டான்,',
        '0.119': 'கொடிய உருவமுடைய அச்சமூட்டும் பல ராக்ஷஸர்களுடன் செல்லுமாறு. வலிமைமிக்க, போர்த்திறமையுடைய அந்த ராக்ஷஸனை',
        '0.120': 'அவனது பின்வருவோருடன் மிகக் கொடிய இரும்புத் தண்டால் கொன்றேன். அதைக் கேட்டு ராக்ஷஸ அரசன் ராவணன் மாவலிமையுடைய அமைச்சர் மைந்தர்களை,',
        '0.121': 'வலிய காலாட்படையுடன் அனுப்பினான்; அவர்கள் அனைவரையும் இரும்புத் தண்டாலேயே யமனுலகிற்கு அனுப்பினேன்.',
        '0.122': 'வேகமிக்க அமைச்சர் மைந்தர்கள் போரில் கொல்லப்பட்டதைக் கேட்டு ராவணன் ஐந்து வீரச் சேனாதிபதிகளை அனுப்பினான்.',
        '0.123': 'அவர்கள் அனைவரையும் சேனையுடன் கொன்றேன். பின்னர் மீண்டும் பத்துக்கழுத்தன் மாவலிமையுடைய தன் மகன் அக்ஷனை',
        '0.124': 'பல ராக்ஷஸர்களுடன் போருக்கு அனுப்பினான். போர்த்திறனுடைய மண்டோதரியின் மகனான அந்த இளவரசனை,',
        '0.125': 'அவன் திடீரென வானில் எழுந்தான்; நான் அவன் கால்களைப் பற்றி நூறு முறை சுழற்றி அடித்து நசுக்கினேன்.',
        '0.126': 'அக்ஷன் வந்து அழிந்ததைக் கேட்டு பத்துத்தலையனான ராவணன் கடுஞ்சினத்துடன் தன் இரண்டாம் மகன் இந்திரஜித்துக்கு ஆணையிட்டான்,',
        '0.127': 'வலியவனும் போரில் வெறிகொண்டவனுமான அவனுக்கு. அந்தச் சேனை முழுவதையும் அந்த ராக்ஷஸ சிரேஷ்டனையும்',
        '0.128': 'போரில் வலிமையிழக்கச் செய்து பேரானந்தம் அடைந்தேன். வலிய கரங்களுடைய மாவலியோனான அவனை ராவணன் பெரும் நம்பிக்கையுடன்',
        '0.129': 'செருக்கால் தலைக்கனம் கொண்ட வீரர்களுடன் அனுப்பியிருந்தான். நான் தாங்கமுடியாதவன் என்றும் தன் சேனை நசுக்கப்பட்டது என்றும் உணர்ந்த அவன்,',
        '0.130': 'மிக வேகமுடைய என்னை பிரம்மாஸ்திரத்தால் கட்டினான்; பின்னர் அங்கிருந்த ராக்ஷஸர்கள் கயிறுகளாலும் என்னைக் கட்டினர்.',
        '0.131': 'அவர்கள் என்னைப் பிடித்து ராவணனிடம் கொண்டு சென்றனர். என்னைக் கண்டு தீயவனான ராவணன் என்னுடன் பேசினான்;',
        '0.132': 'லங்கைக்கு வந்ததையும் ராக்ஷஸர்களைக் கொன்றதையும் பற்றிக் கேட்டான். போர் உட்பட அனைத்தும் சீதைக்காகவே என்று நான் சொன்னேன்:',
        '0.133': '"பிரபுவே, அவளைக் காணும் விருப்பத்துடன் உன் மாளிகைக்கு வந்தேன். நான் வாயுவின் சொந்த மைந்தனான ஹனுமான் என்னும் வானரன்.',
        '0.134': 'என்னை ராமதூதன் என்றும் ஸுக்ரீவனின் அமைச்சனான கபி என்றும் அறி. ராமனின் தூதுக்காக நான் இங்கு உன்னிடம் வந்துள்ளேன்.',
        '0.135': 'நான் சொல்லும் செய்தியையும் கேள். ராக்ஷஸ அரசே, வானர அரசன் உனக்குச் சிந்தித்துச் சொன்ன சொல்லை அனுப்பியுள்ளான்.',
        '0.136': 'பெருமைமிக்க ஸுக்ரீவன் உன் நலத்தை விசாரித்தான்; அறம், பொருள், இன்பம் ஆகியவற்றுக்கு இசைந்த நன்மை தரும் நல்லுரையைச் சொன்னான்:',
        '0.137': '\'பெரிய மரங்கள் நிறைந்த ருஷ்யமூக மலையில் நான் வசித்தபோது, போரில் வீரனான ராகவன் என் நண்பனானான்.',
        '0.138': 'அரசே, அவன் என்னிடம் சொன்னான்: "என் மனைவியை ஒரு ராக்ஷஸன் கவர்ந்து சென்றான்; இதில் உதவ நீ என்னுடன் உடன்படிக்கை செய்ய வேண்டும்."',
        '0.139': 'வாலியால் அரசை இழந்த ஸுக்ரீவனான என்னுடன் பிரபு ராகவன் லக்ஷ்மணனுடன் அக்னியைச் சாட்சியாகக் கொண்டு நட்புக் கொண்டான்.',
        '0.140': 'போரில் ஒரே அம்பால் வாலியைக் கொன்று அவன் என்னை வானரர்களின் மகாராஜனாக, தாவுவோரின் தலைவனாக ஆக்கினான்.',
        '0.141': 'இங்கு நாம் முழுமனதுடன் அவனுக்கு உதவ வேண்டும். அதனால்தான் அறவழிப்படி இவனை உன்னிடம் அனுப்பியுள்ளேன்.',
        '0.142': 'வீரமிக்க வானரர் உன் சேனையை அழிக்கும் முன்பே சீதையை விரைவில் அழைத்து வந்து ராகவனிடம் ஒப்படை.',
        '0.143': 'அழைக்கப்பட்டால் தேவர்களின் முன்னிலைக்கும் செல்லும் வானரர்களின் இந்த வல்லமை முன்பிருந்தே யாருக்குத் தெரியாது?\'',
        '0.144': '\'வானர அரசன் உனக்கு இவ்வாறு சொல்லியுள்ளான்\' என்று நான் சொன்னேன். அப்போது அவன் சினந்து கண்களாலேயே எரிப்பவன் போல் என்னைப் பார்த்தான்.',
        '0.145': 'கொடுஞ்செயலனான தீய ராக்ஷஸன் ராவணன் என் வல்லமையை அறியாமல் என்னைக் கொல்லும்படி ஆணையிட்டான்.',
        '0.146': 'அப்போது அவனுடைய தம்பி பேரறிவாளன் விபீஷணன் எனக்காக ராக்ஷஸ அரசனிடம் வேண்டினான்:',
        '0.147': '"ராக்ஷஸரில் புலியே, அப்படியல்ல; இந்தத் தீர்மானத்தைக் கைவிடு. நீ மேற்கொள்ளும் வழி அரசியல் நூல்களுக்கு முரணாகத் தெரிகிறது.',
        '0.148': 'ராக்ஷஸனே, அரசியல் நூல்களில் தூதனைக் கொல்வது எங்கும் காணப்படவில்லை; தூதன் தனக்குச் சொல்லப்பட்டதையே தெரிவிப்பவன்.',
        '0.149': 'நிகரற்ற வீரனே, தூதன் மிகப் பெரிய குற்றம் செய்தாலும் உருச்சிதைத்தல் மட்டுமே விதிக்கப்பட்டுள்ளது; நூல்களின்படி கொலை இல்லை."',
        '0.150': 'விபீஷணன் இவ்வாறு சொல்ல, ராவணன் அந்த ராக்ஷஸர்களுக்கு ஆணையிட்டான்: "இன்று இவனுடைய இந்த வாலையே கொளுத்துங்கள்."',
        '0.151': 'அவன் சொல்லைக் கேட்டு அவர்கள் என் வாலைச் சுற்றிலும் சணல் நாராலும் பருத்தித் துணிப் பட்டைகளாலும் சுற்றினர்.',
        '0.152': 'பின்னர் ஆயத்தமாக இருந்த அந்தக் கொடிய ராக்ஷஸர்கள் தடிகளாலும் முஷ்டிகளாலும் அடித்தபடி என் வாலுக்குத் தீ வைத்தனர்.',
        '0.153': 'பல கயிறுகளால் கட்டப்பட்டு ராக்ஷஸர்களால் பிடிக்கப்பட்டிருந்தும் எனக்கு எந்த வலியும் இல்லை; பகலில் நகரைப் பார்க்க விரும்பினேன்.',
        '0.154': 'அப்போது அந்த வீர ராக்ஷஸர்கள் கட்டப்பட்டு நெருப்பால் சூழப்பட்ட என்னை அரசவீதியில் பறைசாற்றியபடி நகர வாயிலுக்குக் கொண்டு வந்தனர்.',
        '0.155': 'அப்போது நான் என் பெரிய உருவை மீண்டும் சுருக்கி அந்தக் கட்டிலிருந்து விடுபட்டு மீண்டும் இயல்பான உருவில் நின்றேன்.',
        '0.156': 'இரும்புத் தண்டைப் பற்றி அந்த ராக்ஷஸர்களைக் கொன்றேன்; பின்னர் வேகமாக அந்த நகர வாயிலின் மேல் தாவினேன்.',
        '0.157': 'எரியும் வாலால், பதறாமல், மாடங்களும் கோபுரங்களும் உடைய அந்நகரை, ஊழித்தீ உயிர்களை எரிப்பது போல் எரித்தேன்.',
        '0.158': '"ஜானகி நிச்சயமாக அழிந்திருப்பாள்; ஏனெனில் லங்கையின் எந்தப் பகுதியும் எரியாமல் தெரியவில்லை; நகர் முழுவதும் சாம்பலாகிவிட்டது.',
        '0.159': 'லங்கையை எரிக்கும்போது சீதையையும் எரித்துவிட்டேன், ஐயமில்லை; ராமனின் இந்தப் பெரும் காரியத்தை நான் பயனற்றதாக்கிவிட்டேன்."',
        '0.160': 'இவ்வாறு துயரில் ஆழ்ந்து நான் கவலைக்குள்ளானேன். அப்போது சாரணர்களின் மங்கலச் சொற்களைக் கேட்டேன்;',
        '0.161': '"ஜானகி எரியவில்லை" என்று அவர்கள் வியப்பான செய்தியைச் சொல்லிக்கொண்டிருந்தனர். அந்த அற்புதச் சொல்லைக் கேட்டு எனக்குத் தோன்றியது,',
        '0.162': 'ஜானகி எரியவில்லை என்றே; சகுனங்களாலும் அது தெரிந்தது: வால் எரிந்துகொண்டிருந்தும் நெருப்பு என்னை எரிக்கவில்லை,',
        '0.163': 'என் இதயம் மகிழ்ச்சியால் நிறைந்தது, நறுமணக் காற்று வீசியது. தெளிவான பொருளுடைய அந்தச் சகுனங்களாலும் பெரும் நற்பண்புடைய காரணங்களாலும்',
        '0.164': 'தெளிவான பொருளுடைய ரிஷிகளின் சொற்களாலும் நான் மனம் மகிழ்ந்தேன். மீண்டும் வைதேஹியைக் கண்டு அவளிடம் மீண்டும் விடைபெற்றேன்.',
        '0.165': 'பின்னர் அங்குள்ள அரிஷ்ட மலையில் ஏறி உங்களைக் காணும் ஆவலுடன் திரும்பும் தாவலைத் தொடங்கினேன்.',
        '0.166': 'பின்னர் காற்று, சந்திரன், சூரியன், சித்தர், கந்தர்வர் செல்லும் வழியைக் கடந்து இங்கு உங்களைக் கண்டேன்.',
        '0.167': 'ராகவனின் அருளாலும் உங்கள் அனைவரின் ஒளியாலும் ஸுக்ரீவனின் காரியத்திற்காக நான் அனைத்தையும் நிறைவேற்றினேன்.',
        '0.168': 'இவை அனைத்தையும் நான் அங்கு முறைப்படி செய்து முடித்தேன்; அங்கு செய்யப்படாமல் எஞ்சியவை அனைத்தையும் இப்போது செய்வோம்."',
        '0.169': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் ஐம்பத்தெட்டாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sundarakanda-59': {
      verses: {
        '0.0': 'இவை அனைத்தையும் சொல்லி முடித்த வாயுமைந்தன் ஹனுமான் மேலும் பேசத் தொடங்கினான்:',
        '0.1': '"ராகவனின் முயற்சியும் ஸுக்ரீவனின் ஊக்கமும் பலன் தந்தன; சீதையின் ஒழுக்கத்தைக் கண்டு என் மனமும் மகிழ்ந்தது.',
        '0.2': 'வானரரில் சிறந்தவர்களே, மேன்மையான சீதையின் ஒழுக்கம் எத்தகையதெனில் அவள் தவத்தால் உலகங்களைத் தாங்கவும் முடியும், சினந்தால் எரித்துவிடவும் முடியும்.',
        '0.3': 'ராக்ஷஸ அரசன் ராவணன் எல்லா வகையிலும் மிக வலியவனாகவே இருக்க வேண்டும்; ஏனெனில் அவளைத் தொட்டபோதும் அவனுடைய உடல் அவள் தவத்தால் அழியவில்லை.',
        '0.4': 'சினத்தால் கலங்கிய ஜனகனின் மகள் செய்யக்கூடியதைக் கையால் தொட்ட நெருப்புச் சுடரும் செய்யாது.',
        '0.5': 'ஜாம்பவான் முதலான மாகபிகள் அனைவரின் அனுமதியுடன் சொல்கிறேன்: காரியம் இந்நிலையை அடைந்து உங்களுக்குத் தெரிவிக்கப்பட்டதால், வைதேஹியுடனேயே அந்த இரு இளவரசர்களையும் காண்பதே முறை.',
        '0.6': 'ராக்ஷஸக் கூட்டங்களுடன் அந்த லங்கா நகரையும் மாவலியோனான ராவணனையும் வலிமையால் அழிக்க நான் ஒருவனே போதும்;',
        '0.7': 'அப்படியிருக்க வீரர்களும் வலியவர்களும் உறுதியுள்ளவர்களும் அஸ்திரத் திறனுடையவர்களும் வெற்றியை விரும்புபவர்களுமான உங்களுடன் சேர்ந்தால் சொல்லவும் வேண்டுமோ!',
        '0.8': 'நான் போரில் ராவணனை அவனது சேனை, முன்னணி வீரர்கள், மைந்தர்கள், சகோதரர்களுடன் சேர்த்துக் கொல்வேன்.',
        '0.9': 'இந்திரஜித்தின் பிராம்ம, ரௌத்ர, வாயவ்ய, வாருண அஸ்திரங்கள் போரில் பார்க்கவும் முடியாதவையாயினும், நான் அவற்றை முறியடித்து ராக்ஷஸர்களைச் சிதறடிப்பேன்.',
        '0.10': 'உங்கள் அனுமதி கிடைத்தால் என் வீரம் அவனைத் தடுக்கும். நான் பொழியும் இணையற்ற இடைவிடாத பாறை மழை',
        '0.11': 'போரில் தேவர்களையும் கொல்லக்கூடியது, அந்த இரவுலாவிகளைப் பற்றிச் சொல்வானேன்! உங்கள் அனுமதி இல்லாததால்தான் என் வீரம் என்னைத் தடுக்கிறது.',
        '0.12': 'கடல் கரையைக் கடக்கலாம், மந்தர மலை அசையலாம்; ஆனால் போரில் பகைச்சேனை ஜாம்பவானை அசைக்க முடியாது.',
        '0.13': 'வாலியின் மகனான வீரக் கபி ஒருவனே எல்லா ராக்ஷஸக் கூட்டங்களையும் மூத்த ராக்ஷஸர்களையும் அழிக்க வல்லவன்.',
        '0.14': 'மகாத்மாவான வானரன் நீலனின் தொடைகளின் வேகத்தால் மந்தர மலையும் நொறுங்கலாம், போரில் ராக்ஷஸர்களைப் பற்றிச் சொல்வானேன்!',
        '0.15': 'தேவர், அசுரர், யக்ஷர், கந்தர்வர், நாகர், பறவைகள் இவர்களுள் மைந்தனையோ த்விவிதனையோ எதிர்த்துப் போரிடக்கூடியவன் யாரெனச் சொல்லுங்கள்.',
        '0.16': 'அசுவினி தேவர்களின் மைந்தர்களான இந்த இரு சிறந்த வானரர் பெரும் வேகமுடையவர்; போர்க்களத்தில் இவர்களை எதிர்க்கக்கூடியவனை நான் காணவில்லை.',
        '0.17': 'நான் ஒருவனே லங்கையைத் தாக்கினேன்; நகரம் எரிந்து சாம்பலானது. எல்லா அரச வீதிகளிலும் என் பெயரை முழங்கினேன்:',
        '0.18': '\'பெருவலியோனான ராமனுக்கு வெற்றி, மாவலியோனான லக்ஷ்மணனுக்கு வெற்றி! ராகவனால் காக்கப்படும் அரசன் ஸுக்ரீவனுக்கு வெற்றி!',
        '0.19': 'நான் கோசல அரசனின் அடியான், வாயுமைந்தன், ஹனுமான் என்பது என் பெயர்\' என்று எங்கும் என் பெயரை முழங்கினேன்.',
        '0.20': 'தீய ராவணனின் அசோகவனத்தின் நடுவே சிம்சுபா மரத்தின் அடியில் அந்தக் கற்புடையவள் இரங்கத்தக்க நிலையில் இருக்கிறாள்;',
        '0.21': 'ராக்ஷஸிகளால் சூழப்பட்டு, துயரத்தாலும் வேதனையாலும் மெலிந்து, மேகக்கோட்டால் மறைக்கப்பட்ட பிறைநிலவு போல் ஒளியிழந்திருக்கிறாள்.',
        '0.22': 'வலிமையால் செருக்குற்ற ராவணனை வைதேஹி பொருட்படுத்துவதில்லை; கற்புடைய அழகி ஜானகி உறுதியாக நிற்கிறாள்.',
        '0.23': 'மங்கலமான வைதேஹி முழுமனதுடன் ராமனிடமே அன்புகொண்டவள்; பௌலோமி (சசி) இந்திரனிடம் இருப்பது போல் அவள் மனம் ராமனைத் தவிர வேறெங்கும் இல்லை.',
        '0.24': 'அதே ஒற்றை ஆடையைச் சுற்றிக்கொண்டு, புழுதி படிந்து, ராக்ஷஸிகளிடையே மீண்டும் மீண்டும் மிரட்டப்பட்ட அவளை',
        '0.25': 'விகாரமான ராக்ஷஸிகளால், இன்பவனத்தில் கண்டேன்; ஒற்றைச் சடையுடன், துயருற்று, கணவனின் நினைவிலேயே மூழ்கியிருந்தாள்;',
        '0.26': 'தரையில் படுத்து, பனிக்காலத் தொடக்கத்தில் தாமரைக்கொடி போல் வாடி, ராவணனிடமிருந்து மனதைத் திருப்பி, இறக்கத் தீர்மானித்திருந்தாள்.',
        '0.27': 'மான்குட்டி போன்ற கண்களுடைய அவளிடம் எப்படியோ நம்பிக்கை உண்டாக்கினேன்; பின்னர் அவளுடன் பேசி எல்லா விஷயத்தையும் தெரிவித்தேன்.',
        '0.28': 'ராமன்-ஸுக்ரீவன் நட்பைக் கேட்டு அவள் மகிழ்ந்தாள். அவள் நடத்தை கட்டுப்பாடானது, கணவனிடம் அவள் பக்தி மிக உயர்ந்தது.',
        '0.29': 'அந்த மகாத்மா பத்துக்கழுத்தனைத் தானே கொல்லாதிருப்பது, அவனது அழிவுக்கு ராமன் கருவியாக மட்டும் அமையட்டும் என்பதற்காகவே.',
        '0.30': 'இயல்பாகவே மெல்லிய உடலுடையவள், அவனைப் பிரிந்ததால் மேலும் மெலிந்து, பிரதமை (விலக்கப்பட்ட நாள்) அன்று ஓதுபவனின் கல்வி போல் தேய்ந்துவிட்டாள்.',
        '0.31': 'இவ்வாறு பெருமைமிக்க சீதை துயரில் ஆழ்ந்திருக்கிறாள். இதில் செய்ய வேண்டிய பரிகாரம் அனைத்தையும் ஏற்பாடு செய்யுங்கள்."',
        '0.32': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் ஐம்பத்தொன்பதாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sundarakanda-60': {
      verses: {
        '0.0': 'அவனது சொல்லைக் கேட்டு வாலியின் மகன் கூறினான்: "அசுவினி தேவர்களின் மைந்தர்களான இந்த இரு வானரரும் பெரும் வேகமும் வலிமையும் உடையவர்கள்.',
        '0.1': 'பிரம்மாவின் வரத்தால் செருக்குற்று அவர்கள் மிகுந்த ஆணவம் கொண்டுள்ளனர்; அசுவினி தேவர்களைக் கௌரவிக்கவே அனைத்துலகப் பிதாமகன்',
        '0.2': 'முன்பு இவர்களுக்கு யாராலும் கொல்லப்படாத இணையற்ற வரத்தைக் கொடுத்தான். அந்த வரத்தின் மயக்கத்தால் இந்த வீரர்கள் ஒரு பெரும் சேனையை நசுக்கி',
        '0.3': 'மாவலிமையுடைய இவர்கள் தேவர்களின் அமுதத்தைப் பருகினர். சினந்தால் இவ்விருவரே குதிரைகள், தேர்கள், யானைகளுடன்',
        '0.4': 'லங்கையை அழிக்க வல்லவர்கள்; மற்ற வானரர் அனைவரும் சும்மா இருக்கட்டும். ராக்ஷஸக் கூட்டங்களுடன் அந்த லங்கா நகரை அழிக்க நான் ஒருவனே போதும்,',
        '0.5': 'மாவலியோனான ராவணனையும் வலிமையால் கொல்ல; அப்படியிருக்க வீரர்களும் வலியவர்களும் உறுதியுள்ளவர்களுமான',
        '0.6': 'அஸ்திரத் திறனுடையவர்களும் வல்லவர்களும் வெற்றியை விரும்புபவர்களுமான உங்களைப் போன்ற வானரர்களுடன் சேர்ந்தால் சொல்லவும் வேண்டுமோ! வாயுமைந்தனின் வலிமையாலேயே லங்கை எரிந்தது என்று கேட்டோம்.',
        '0.7': '\'தேவியைக் கண்டோம், ஆனால் அழைத்து வரவில்லை\' என்று அங்கு தெரிவிப்பது புகழ்பெற்ற வீரமுடைய உங்களுக்குத் தகுந்ததாக எனக்குத் தோன்றவில்லை.',
        '0.8': 'வானரரில் சிறந்தவர்களே, தேவர்-தைத்யர் உட்பட எந்த உலகிலும் தாவுவதிலோ வீரத்திலோ உங்களுக்கு நிகர் யாருமில்லை.',
        '0.9': 'ராக்ஷஸக் கூட்டங்களுடன் லங்கையை வென்று, போரில் அந்த ராவணனைக் கொன்று, சீதையை அழைத்துக்கொண்டு காரியம் முடித்தவர்களாக மகிழ்ச்சியுடன் செல்வோம்.',
        '0.10': 'ஹனுமானால் இத்தனை ராக்ஷஸ வீரர்கள் கொல்லப்பட்ட பின் இங்கு வேறென்ன செய்ய வேண்டும்? ஜானகியை அழைத்துக்கொண்டு செல்வோம்.',
        '0.11': 'ஜனகனின் மகளை ராம லக்ஷ்மணருக்கு நடுவே கொண்டு சேர்ப்போம். மற்ற வானரர்களையும் வானரத் தலைவர்களையும் வீணாகத் தொந்தரவு செய்வானேன்?',
        '0.12': 'நாமே சென்று அந்தத் தலைசிறந்த ராக்ஷஸர்களைக் கொன்று, பின்னர் ராகவனையும் ஸுக்ரீவனையும் லக்ஷ்மணனையும் காணச் செல்வோம்."',
        '0.13': 'இவ்வாறு தீர்மானித்த அவனிடம், கடமையை அறிந்த வானரரில் சிறந்த ஜாம்பவான் மிகுந்த அன்புடன் பொருள் நிறைந்த இச்சொல்லைச் சொன்னான்:',
        '0.14': '"பேரறிவுடைய மாகபியே, நீ சொல்வது சரியான எண்ணமல்ல. சிறந்த தென்திசையைத் தேடுமாறு மட்டுமே நமக்கு ஆணையிடப்பட்டது;',
        '0.15': 'அவளை அழைத்து வருமாறு வானர அரசனோ அறிவுடைய ராமனோ ஆணையிடவில்லை. நம்மால் எப்படியோ வென்று கொண்டுவரப்பட்ட சீதையை அவன் விரும்பமாட்டான்.',
        '0.16': 'அரசர்களில் புலியான ராகவன் தன் குலத்தைக் குறிப்பிட்டு, சீதையைத் தானே வென்று மீட்பேன் என்று அனைவர் முன்னிலையிலும் சபதம் செய்துள்ளான்.',
        '0.17': 'எல்லா வானரத் தலைவர்களின் முன் செய்த அந்தச் சபதத்தை அவன் எப்படிப் பொய்யாக்குவான்? அப்போது நாம் செய்த செயல் பயனற்றதாகும், அவனுக்கும் மனநிறைவு இராது.',
        '0.18': 'வானரத் தலைவர்களே, நாம் காட்டிய வீரமும் வீணாகும். ஆகவே இக்காரியத்தைத் தெரிவிக்க லக்ஷ்மணனுடன் ராமனும் மாபெரும் ஒளியுடைய ஸுக்ரீவனும் இருக்குமிடத்திற்கு நாம் அனைவரும் செல்வோம்."',
        '0.19': '"இளவரசே, நீ காண்பது போல் இந்த எண்ணம் நமக்குத் தகாததல்ல; ஆனால் ராமனின் மனம் எப்படி உறுதியாக உள்ளதோ அப்படியே நீ காரியசித்தியை நோக்கு."',
        '0.20': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் அறுபதாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sundarakanda-61': {
      verses: {
        '0.0': 'பின்னர் அங்கதன் முதலான காட்டுவாழ் வீரர்களும் மாகபி ஹனுமானும் ஜாம்பவானின் சொல்லை ஏற்றுக்கொண்டனர்.',
        '0.1': 'அப்போது மகிழ்ச்சி நிறைந்த சிறந்த வானரர் அனைவரும் வாயுமைந்தனை முன்னிறுத்தி மகேந்திரத்தின் உச்சியிலிருந்து எழுந்து பறந்தனர்.',
        '0.2': 'மேரு, மந்தர மலைகளைப் போலவும், மதம் கொண்ட பெரும் யானைகளைப் போலவும் இருந்த அந்தப் பேருடல் கொண்ட மாவலியோர் வானையே மறைப்பது போலிருந்தனர்.',
        '0.3': 'எல்லா உயிர்களாலும் போற்றப்பட்ட, தன்னடக்கமுள்ள, மாவலியோனும் பெருவேகமுடையவனுமான ஹனுமானை அவர்கள் தங்கள் பார்வையாலேயே சுமந்து செல்வது போல் நோக்கினர்.',
        '0.4': 'ராகவனின் காரியசித்தியையும் மேலான புகழையும் அடைய உறுதிபூண்ட அவர்கள், காரியம் கைகூடியதால் உற்சாகமடைந்து நோக்கம் நிறைவேறியவர்களாக இருந்தனர்.',
        '0.5': 'அனைவரும் இனிய செய்தியைச் சொல்ல ஆவலுற்றவர், அனைவரும் போரை வரவேற்பவர், அனைவரும் ராமனுக்காகப் பழிதீர்ப்பதில் உறுதிகொண்ட மனவலிமையோர்.',
        '0.6': 'வானில் தாவிப் பறந்து அந்தக் காட்டுவாசிகள் நந்தனவனத்திற்கு நிகரான, லட்சக்கணக்கான மரங்கள் கொண்ட ஒரு வனத்தை அடைந்தனர்.',
        '0.7': 'அதுவே மதுவனம் எனப் பெயர்பெற்ற, ஸுக்ரீவனால் காக்கப்பட்ட, எந்த உயிரும் நுழைய முடியாத, அனைவர் மனதையும் கவரும் வனம்.',
        '0.8': 'வானரத் தலைவனான மகாத்மா ஸுக்ரீவனின் தாய்மாமனான மாவீரன் ததிமுகன் என்ற கபி அதை எப்போதும் காத்து வந்தான்.',
        '0.9': 'வானர அரசனின் மனதுக்கு இனிய அந்தப் பெருவனத்தை அடைந்ததும் வானரர் மிகுந்த களிப்பில் துள்ளினர்.',
        '0.10': 'அப்போது பெரிய மதுவனத்தைக் கண்டு மகிழ்ந்த தேன்நிற வானரர் இளவரசனிடம் தேன் வேண்டினர்.',
        '0.11': 'அப்போது இளவரசன் ஜாம்பவான் முதலான மூத்த கபிகளின் சம்மதம் பெற்று அவர்களுக்குத் தேன் உண்ண அனுமதி தந்தான்.',
        '0.12': 'அறிவுடைய வாலியின் மகனான இளவரசனிடம் அனுமதி பெற்ற வானரர் வண்டுகள் மொய்க்கும் மரங்களில் ஏறினர்.',
        '0.13': 'நறுமணமுள்ள கிழங்குகளையும் கனிகளையும் உண்டு அவர்கள் அனைவரும் மகிழ்ந்து மயக்கத்தால் வெறிகொண்டனர்.',
        '0.14': 'அனுமதி பெற்ற காட்டுவாசிகள் அனைவரும் பெருமகிழ்ச்சியடைந்து, களிப்புடன் அங்குமிங்கும் ஆடினர்.',
        '0.15': 'சிலர் பாடினர், சிலர் சிரித்தனர், சிலர் ஆடினர், சிலர் வணங்கினர்; சிலர் விழுந்தனர், சிலர் திரிந்தனர், சிலர் தாவினர், சிலர் உளறினர்.',
        '0.16': 'சிலர் ஒருவரையொருவர் சாய்ந்துகொண்டனர், சிலர் ஒருவருக்கொருவர் வாக்குவாதம் செய்தனர்; சிலர் மரத்திலிருந்து மரத்திற்கு ஓடினர், சிலர் மர உச்சிகளிலிருந்து தரையில் குதித்தனர்.',
        '0.17': 'சிலர் பொங்கிய வேகத்துடன் தரையிலிருந்து பெரிய மரங்களின் உச்சிகளுக்குத் தாவினர்; பாடுபவனிடம் ஒருவன் சிரித்தபடி சென்றான், சிரிப்பவனிடம் இன்னொருவன் அழுதபடி சென்றான்.',
        '0.18': 'குத்துபவனிடம் வேறொருவன் கத்தியபடி சென்றான்; அந்த வானரச் சேனை முழுவதும் கூச்சலும் குழப்பமுமாக இருந்தது. அங்கு மயக்கமடையாதவனும் செருக்குறாதவனும் ஒருவருமில்லை.',
        '0.19': 'அப்போது அந்த வனம் தின்னப்படுவதையும் மரங்களின் இலைகளும் பூக்களும் அழிக்கப்படுவதையும் கண்டு ததிமுகன் எனும் கபி சினத்துடன் அந்தக் கபிகளைத் தடுத்தான்.',
        '0.20': 'அந்த வெறிகொண்ட வானரர்களால் திட்டப்பட்ட, கடுமையான ஒளியுடைய வனக்காவலனான அந்த முதிய வானர வீரன் மீண்டும் வானரர்களிடமிருந்து வனத்தைக் காக்கத் தீர்மானித்தான்.',
        '0.21': 'அவன் அஞ்சாமல் சிலரிடம் கடுஞ்சொற்கள் பேசினான், சிலரை உள்ளங்கைகளால் பலமாக அறைந்தான், சிலருடன் சண்டையிட்டான், வேறு சிலரை இனிய சொற்களால் சமாதானப்படுத்த முயன்றான்.',
        '0.22': 'மயக்கத்தால் தடுக்க முடியாத வேகமுடைய அவர்கள், அவன் வலுக்கட்டாயமாகத் தடுக்க, அச்சமின்றி ஒன்றுகூடி அவன் மேல் பாய்ந்து, தவறைப் பொருட்படுத்தாமல் அவனை இழுத்தடித்தனர்.',
        '0.23': 'நகங்களால் கீறி, பற்களால் கடித்து, உள்ளங்கைகளாலும் கால்களாலும் அடித்து அந்தக் கபிகள் மயக்கத்தில் அந்தக் கபியை அரைஉயிராக்கி, பெருவனத்தை வெறுமையாக்கினர்.',
        '0.24': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் அறுபத்தொன்றாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sundarakanda-62': {
      verses: {
        '0.0': 'வானரரில் சிறந்த ஹனுமான் அவர்களிடம் சொன்னான்: "வானரர்களே, கவலையின்றித் தேனை அனுபவியுங்கள்.',
        '0.1': 'உங்களைத் தடுப்பவர்களை நான் விலக்குவேன்." ஹனுமானின் சொல்லைக் கேட்டு வானரரில் முதன்மையான அங்கதன்',
        '0.2': 'மனமகிழ்ந்து பதில் சொன்னான்: "வானரர் தேன் பருகட்டும். காரியத்தை நிறைவேற்றிய ஹனுமானின் சொல்லை நான் அவசியம் நிறைவேற்ற வேண்டும்;',
        '0.3': 'அது செய்யத்தகாத செயலாயினும் செய்ய வேண்டும்; இது போன்றதைப் பற்றிச் சொல்லவும் வேண்டுமோ!" அங்கதனின் வாயிலிருந்து இச்சொல்லைக் கேட்டு வானரத் தலைவர்கள்',
        '0.4': 'மகிழ்ந்து "நன்று, நன்று" என்று அவனைப் போற்றினர். வானரரில் சிறந்த அங்கதனைக் கௌரவித்து வானரர் அனைவரும்',
        '0.5': 'வெள்ளம் பெருக்கெடுத்த நதி மரத்தின் மேல் பாய்வது போல் மதுவனத்துள் பாய்ந்தனர். மதுவனத்துள் நுழைந்து காவலர்களை வலிமையால் அடக்கி,',
        '0.6': 'அனுமதி கிடைத்த துணிவாலும் மைதிலியைக் கண்டதும் கேட்டதுமான மகிழ்ச்சியாலும் அவர்கள் அனைவரும் அப்போது தேனைப் பருகி, சாறுள்ள கனிகளை எடுத்துக்கொண்டனர்.',
        '0.7': 'பின்னர் மேலெழுந்து, எதிர்வந்த நூற்றுக்கணக்கான வனக்காவலர்களை அடித்தபடி அவர்கள் மதுவனத்திலேயே மூழ்கினர்.',
        '0.8': 'சில கபிகள் துரோண அளவுள்ள தேன்கூடுகளைக் கைகளில் அணைத்துக்கொண்டு கூட்டம் கூட்டமாக மகிழ்ச்சியுடன் பருகினர்.',
        '0.9': 'சிலர் ஒன்றுசேர்ந்து காவலர்களை அடித்தனர், வேறு சிலர் உண்டனர்; தேன்நிறமுடைய சிலர் பருகிவிட்டு மீதித் தேனை வீசியெறிந்தனர்.',
        '0.10': 'வெறிகொண்ட சிலர் தேன்மெழுகால் ஒருவரையொருவர் அடித்துக்கொண்டனர்; வேறு சிலர் கிளைகளைப் பற்றியபடி மரங்களின் அடியில் அமர்ந்தனர்.',
        '0.11': 'மயக்கத்தால் மிகவும் சோர்ந்த சிலர் இலைகளைப் பரப்பிப் படுத்தனர்; வெறிகொண்ட வேகமுடைய வானரர் தேனால் மயங்கி மகிழ்ந்திருந்தனர்;',
        '0.12': 'ஒருவரையொருவர் தள்ளினர், வேறு சிலர் தடுமாறினர்; சிலர் சிம்மநாதம் செய்தனர், சிலர் மகிழ்ச்சியுடன் கூவினர்.',
        '0.13': 'தேனால் மயங்கிய சில கபிகள் தரையில் உறங்கினர்; சில துடுக்கர் சிரித்தனர், வேறு சிலர் அதற்கு மாறானதைச் செய்தனர்.',
        '0.14': 'சிலர் ஒன்றைச் செய்து வேறொன்றைச் சொன்னனர், சிலர் ஒன்றை வேறொன்றாகப் புரிந்துகொண்டனர். அங்கிருந்த ததிமுகனின் பணியாட்களான தேன்காவலர்கள்',
        '0.15': 'அந்தக் கொடிய வானரர்களால் விரட்டப்பட்டுத் திசைதோறும் ஓடினர்; முழங்கால்களில் இழுக்கப்பட்டு வானில் தூக்கி வீசப்பட்டனர்.',
        '0.16': 'மிகவும் கலங்கிய அவர்கள் ததிமுகனிடம் சென்று சொன்னார்கள்: "ஹனுமானிடம் அனுமதி பெற்றவர்கள் வலுக்கட்டாயமாக மதுவனத்தை அழித்துவிட்டனர்; எங்களை முழங்கால்களில் இழுத்து வானில் வீசினர்."',
        '0.17': 'அப்போது வனக்காவலனான வானரன் ததிமுகன் மதுவனம் அழிக்கப்பட்டதைக் கேட்டுச் சினந்து அந்தக் கபிகளை ஆறுதல்படுத்தினான்:',
        '0.18': '"வாருங்கள், வாருங்கள், மிகுந்த செருக்குற்ற அந்த வானரர்களிடம் செல்வோம்; சிறந்த தேனை அனுபவிக்கும் அவர்களை நான் வலிமையால் தடுப்பேன்."',
        '0.19': 'ததிமுகனின் இச்சொல்லைக் கேட்டு அந்த வீர வானரர் அவனுடன் சேர்ந்து மீண்டும் மதுவனத்திற்குச் சென்றனர்.',
        '0.20': 'அவர்கள் நடுவே ததிமுகன் ஒரு பெரிய மரத்தை இறுகப் பற்றி வேகமாக முன்னேறினான்; அந்தக் கபிகள் அனைவரும் அவனுடன் ஓடினர்.',
        '0.21': 'சினந்த அந்த வானரர் பாறைகளையும் மரங்களையும் கற்களையும் எடுத்துக்கொண்டு அந்தச் சிறந்த கபிகள் இருந்த இடத்திற்கு வந்தனர்.',
        '0.22': 'வலிமையால் தடுத்தபடி அந்த வானரர் அந்த வானரர்களை நெருங்கினர்; சினத்தால் உதடுகளைக் கடித்தபடி மீண்டும் மீண்டும் மிரட்டினர்.',
        '0.23': 'அப்போது சினந்த ததிமுகனைக் கண்டு ஹனுமான் முதலான சிறந்த வானரர் வேகமாக அவனை நோக்கிப் பாய்ந்தனர்.',
        '0.24': 'மரத்துடன் பாய்ந்து வந்த வலிய கரங்களும் பெருவலிமையும் வேகமும் உடைய அவனைச் சினந்த அங்கதன் இரு கைகளாலும் பற்றினான்.',
        '0.25': '"இவர் என் மூத்தவர்" என்பதையும் பொருட்படுத்தாமல், மயக்கத்தால் கண்மூடிய அவன் இரக்கம் காட்டாமல் விரைவில் அவரை வேகமாகத் தரையில் அடித்து நசுக்கினான்.',
        '0.26': 'கைகளும் தொடைகளும் முகமும் நொறுங்கி, கலங்கி, இரத்தத்தில் நனைந்த அந்த மாவீரக் கபிசிரேஷ்டன் சிறிது நேரம் மயங்கினான்.',
        '0.27': 'அந்த வானரர்களிடமிருந்து எப்படியோ விடுபட்ட அந்த வானர சிரேஷ்டன் தனியிடத்திற்குச் சென்று, அங்கு கூடியிருந்த தன் பணியாட்களிடம் சொன்னான்:',
        '0.28': '"வாருங்கள், வாருங்கள், நம் தலைவன், அகன்ற கழுத்துடைய வானரன் ஸுக்ரீவன் ராமனுடன் இருக்குமிடத்திற்குச் செல்வோம்.',
        '0.29': 'அங்கதனின் குற்றம் முழுவதையும் அரசனிடம் சொல்வோம்; அதைக் கேட்டுச் சினமுள்ள அவன் அந்த வானரர்களைக் கொல்வான்.',
        '0.30': 'இந்த மதுவனம் மகாத்மா ஸுக்ரீவனுக்கு இனியது; தந்தை, பாட்டன் வழி வந்த தெய்வீக வனம், தேவர்களுக்கும் அணுகமுடியாதது.',
        '0.31': 'தேனாசையால் ஆயுள் முடிந்த இந்த வானரர் அனைவரையும் அவர்களின் நண்பர்களுடன் ஸுக்ரீவன் தண்டித்துக் கொல்வான்.',
        '0.32': 'அரசனின் ஆணையை மீறிய இந்தத் தீயவர்கள் கொல்லத்தக்கவர்கள்; பொறுமையின்மையால் எழுந்த என் சினம் பலன் தரும்."',
        '0.33': 'வனக்காவலர்களிடம் இவ்வாறு சொல்லி மாவலியோனான ததிமுகன் திடீரென எழும்பி அவர்களுடன் புறப்பட்டான்.',
        '0.34': 'இமைப்பொழுதில் அந்த வனவாசி ஆயிரம் கதிருடைய சூரியனின் மகனான அறிவுடைய வானரன் ஸுக்ரீவன் இருந்த இடத்தை அடைந்தான்.',
        '0.35': 'ராமனையும் லக்ஷ்மணனையும் ஸுக்ரீவனையும் கண்டு அவன் வானிலிருந்து சமதளமான தரையில் இறங்கினான்.',
        '0.36': 'இறங்கிய மாவீரனும் காவலர்களின் தலைவனுமான வானரன் ததிமுகன் அக்காவலர்கள் அனைவராலும் சூழப்பட்டு,',
        '0.37': 'வாடிய முகத்துடன் தலைமேல் கைகூப்பி, விரைவில் ஸுக்ரீவனின் பாதங்களில் தலைவைத்து வணங்கினான்.',
        '0.38': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் அறுபத்திரண்டாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sundarakanda-63': {
      verses: {
        '0.0': 'பாதங்களில் தலைவைத்து விழுந்திருந்த அந்த வானரனைக் கண்டு வானரத் தலைவன் கலங்கிய உள்ளத்துடன் இச்சொல்லைக் கூறினான்:',
        '0.1': '"எழு, எழு! நீ ஏன் என் பாதங்களில் விழுந்தாய்? உனக்கு அபயம் அளிக்கிறேன்; உண்மையைச் சொல்.',
        '0.2': 'இந்தப் பதற்றம் ஏன்? சொல்ல வேண்டிய நன்மையானது அனைத்தையும் சொல். மதுவனத்தில் நலம்தானா? வானரனே, கேட்க விரும்புகிறேன்."',
        '0.3': 'மகாத்மா ஸுக்ரீவனால் ஆறுதல் பெற்ற பேரறிஞன் ததிமுகன் எழுந்து இச்சொல்லைச் சொன்னான்:',
        '0.4': '"அரசே, ருக்ஷரஜஸோ, நீயோ, வாலியோ முன்பு ஒருபோதும் திறந்துவிடாத உன் வனத்தை வானரர் அழித்துவிட்டனர்.',
        '0.5': 'நான் இந்த வனசாரிகளுடன் அவர்கள் அனைவரையும் தடுத்தேன்; ஆனால் என்னைப் பொருட்படுத்தாமல் அவர்கள் மகிழ்ச்சியுடன் உண்கிறார்கள், பருகுகிறார்கள்.',
        '0.6': 'இந்த வனக்காவலர்கள் அவர்களின் தாக்குதலைத் தடுத்தபோது, தேவனே, அந்த வனவாசிகள் என்னையும் பொருட்படுத்தாமல் உண்டுகொண்டே இருந்தனர்.',
        '0.7': 'சிலர் மீதியை வீசியெறிகின்றனர், வேறு சிலர் உண்கின்றனர்; தடுக்கப்படும்போது அவர்கள் அனைவரும் புருவத்தை நெரிக்கின்றனர்.',
        '0.8': 'இந்தக் காவலர்கள் மேலும் சினந்தபோது அவர்களால் தாக்கப்பட்டனர்; சினந்த அந்த வானரத் தலைவர்கள் இவர்களை அந்த வனத்திலிருந்து விரட்டினர்.',
        '0.9': 'அப்போது சினத்தால் சிவந்த கண்களுடைய அந்தப் பல வீர வானரர் இந்தச் சிறந்த வானரர்கள் மேல் தாக்குதல் நடத்தினர்.',
        '0.10': 'சிலரை உள்ளங்கைகளால் அடித்தனர், சிலரை முழங்கால்களால் தாக்கினர்; விருப்பம்போல் இழுத்து வானில் வீசினர்.',
        '0.11': 'தலைவனான நீ இருக்கும்போதே இந்த வீரர்கள் இவ்வாறு அடிபட்டனர்; மதுவனம் முழுவதையும் அவர்கள் விருப்பம்போல் உண்கின்றனர்."',
        '0.12': 'வானரத் தலைவன் ஸுக்ரீவனிடம் இவ்வாறு தெரிவிக்கப்பட்டபோது, பகைவீரரைக் கொல்லும் பேரறிஞன் லக்ஷ்மணன் அவனைக் கேட்டான்:',
        '0.13': '"அரசே, வனக்காவலனான இந்த வானரன் ஏன் வந்துள்ளான்? எதைக் குறித்து இவன் துயரத்துடன் பேசினான்?"',
        '0.14': 'மகாத்மா லக்ஷ்மணன் இவ்வாறு கேட்க, சொல்வன்மையுடைய ஸுக்ரீவன் லக்ஷ்மணனுக்கு இவ்வாறு பதில் சொன்னான்:',
        '0.15': '"ஐயனே லக்ஷ்மணா, அங்கதன் முதலான வீர வானரர் தேனை உண்டுவிட்டனர் என்று வீரக் கபி ததிமுகன் சொல்கிறான்.',
        '0.16': 'காரியத்தை முடிக்காதிருந்தால் இவர்கள் இத்தகைய மீறலைச் செய்திருக்க மாட்டார்கள்; அவர்கள் வனத்தை முற்றுகையிட்டார்கள் என்றால் காரியம் நிச்சயமாக நிறைவேறிவிட்டது.',
        '0.17': 'தடுக்க வந்த காவலர்கள் முழங்கால்களால் அடிக்கப்பட்டனர்; வலிமைமிக்க இந்தக் கபி ததிமுகனையும் அவர்கள் பொருட்படுத்தவில்லை,',
        '0.18': 'அவன் நானே நியமித்த என் வனத்தின் தலைவனாக இருந்தும். தேவியைக் கண்டுவிட்டனர், ஐயமில்லை; அதுவும் ஹனுமானே கண்டான், வேறு யாருமல்ல.',
        '0.19': 'இக்காரியத்தை நிறைவேற்ற ஹனுமானைத் தவிர வேறு யாரும் காரணமாக முடியாது; வானரத் தலைவன் ஹனுமானிடம் காரியசித்தியும் அறிவும் நிலைத்துள்ளன,',
        '0.20': 'உறுதியும் வீரமும் கல்வியும் அவனிடம் நிலைபெற்றுள்ளன. ஜாம்பவான் தலைவனாகவும், மாவலியோனான அங்கதனும் இருந்து,',
        '0.21': 'ஹனுமான் வழிநடத்துபவனாக இருக்குமிடத்தில் வேறு விளைவு இருக்கவே முடியாது. அங்கதன் முதலான வீரர்கள் மதுவனத்தை அழித்தனராம்;',
        '0.22': 'தென்திசையைத் தேடித் திரும்பிய வானரத் தலைவர்கள்; திரும்பி வந்து அவர்கள் அணுகமுடியாத அந்த மதுவனத்தை அழித்துவிட்டனர்.',
        '0.23': 'வானரர் வனம் முழுவதையும் முற்றுகையிட்டு அனுபவித்துள்ளனர்; வனக்காவலர்களை முழங்கால்களால் அடித்து வீழ்த்தியுள்ளனர்.',
        '0.24': 'இதைத் தெரிவிக்கவே இனிமையாகப் பேசும், புகழ்பெற்ற வீரமுடைய ததிமுகன் என்னும் இந்த வானரன் இங்கு வந்துள்ளான்.',
        '0.25': 'வலிய கரங்களுடைய ஸௌமித்ரியே, சீதை காணப்பட்டாள்; வானரர் அனைவரும் வந்து தேன் பருகுவதைக் கொண்டே இது உண்மையென அறி.',
        '0.26': 'ஆண்களில் சிறந்தவனே, வைதேஹியைக் காணாதிருந்தால் புகழ்பெற்ற அந்த வனவாசிகள் அரச ஆணையால் காக்கப்பட்ட அந்தத் தெய்வீக வனத்தை ஒருபோதும் அழித்திருக்க மாட்டார்கள்."',
        '0.27': 'அப்போது ஸுக்ரீவனின் வாயிலிருந்து வந்த செவிக்கு இனிய சொல்லைக் கேட்டு அறவழி நடக்கும் லக்ஷ்மணன் ராகவனுடன் மகிழ்ந்தான்.',
        '0.28': 'ராமன் பெரிதும் மகிழ்ந்தான், புகழ்மிக்க லக்ஷ்மணனும் மகிழ்ந்தான். ததிமுகனின் சொல்லைக் கேட்டு ஸுக்ரீவனும் மகிழ்ந்து,',
        '0.29': 'வனக்காவலனிடம் மீண்டும் சொன்னான்: "காரியத்தை நிறைவேற்றிய அவர்கள் வனத்தை அனுபவித்ததால் நான் மகிழ்கிறேன்.',
        '0.30': 'காரியம் முடித்தவர்களின் அந்த அத்துமீறலைப் பொறுத்துக்கொள்ள வேண்டும். விரைவில் மதுவனத்திற்குச் சென்று நீயே அதைக் காவல் செய்; ஹனுமான் முதலான அந்தக் கபிகள் அனைவரையும் விரைவில் இங்கு அனுப்பு.',
        '0.31': 'சிங்கம் போன்ற செருக்குடைய, காரியம் முடித்த ஹனுமான் தலைமையிலான அந்த வானரர்களை இரு ராகவர்களுடன் விரைவில் விசாரிக்கவும், சீதையைக் கண்டுபிடித்த முயற்சியைக் கேட்கவும் விரும்புகிறேன்."',
        '0.32': 'மகிழ்ச்சியால் விரிந்த கண்களுடன், உவகையுடன், காரியம் கைகூடியவர் போலிருந்த அந்த இளவரசர்களைக் கண்டு, தன் சிலிர்த்த அங்கங்களால் காரியசித்தி கைக்கு எட்டும் தூரத்தில் உள்ளது என்றறிந்த வானர அரசன் அளவற்ற ஆனந்தம் அடைந்தான்.',
        '0.33': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் அறுபத்துமூன்றாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sundarakanda-64': {
      verses: {
        '0.0': 'ஸுக்ரீவன் இவ்வாறு சொல்ல, மகிழ்ந்த கபி ததிமுகன் ராகவனையும் லக்ஷ்மணனையும் ஸுக்ரீவனையும் வணங்கினான்.',
        '0.1': 'ஸுக்ரீவனையும் மாவலிமையுடைய இரு ராகவர்களையும் வணங்கி அவன் வீர வானரர்களுடன் வானில் எழுந்தான்.',
        '0.2': 'முன்பு எப்படி வந்தானோ அப்படியே விரைவாகச் சென்று, வானிலிருந்து தரையில் இறங்கி அந்த வனத்துள் நுழைந்தான்.',
        '0.3': 'மதுவனத்துள் நுழைந்த அவன், மயக்கம் தெளிந்தும் துடுக்காக இருந்த, தேன்நீரைச் சிறுநீராகக் கழித்துக்கொண்டிருந்த வானரப் படைத்தலைவர்களைக் கண்டான்.',
        '0.4': 'அந்த வீரன் கைகூப்பி அவர்களை அணுகி, மகிழ்ச்சியுடன் அங்கதனிடம் இந்த மென்மையான சொல்லைச் சொன்னான்:',
        '0.5': '"சாந்தமானவனே, இந்தக் காவலர்கள் அறியாமையாலும் சினத்தாலும் உங்களைத் தடுத்ததற்காக நீ கோபிக்கக் கூடாது.',
        '0.6': 'நீ களைத்து நெடுந்தொலைவிலிருந்து வந்துள்ளாய்; உன்னுடைய தேனையே அனுபவி. மாவலியோனே, நீ இளவரசன், இந்த வனத்தின் தலைவன்.',
        '0.7': 'மூடத்தனத்தால் முன்பு நான் சினம் காட்டினேன்; அதை நீ மன்னிக்க வேண்டும். முன்பு உன் தந்தை வானரக் கூட்டங்களின் தலைவனாக இருந்தது போல,',
        '0.8': 'நீயும் அப்படியே, ஸுக்ரீவனும் அப்படியே; வானரரில் சிறந்தவனே, வேறு யாருமல்ல. குற்றமற்றவனே, நான் சென்று உன் சிற்றப்பனிடம் தெரிவித்தேன்,',
        '0.9': 'இந்த வனசாரிகள் அனைவரும் இங்கு வந்துள்ளதை. இந்த வனசாரிகளுடன் நீ வந்ததைக் கேட்டு,',
        '0.10': 'வனம் அழிக்கப்பட்டதைக் கேட்டும் அவன் சினக்காமல் மகிழ்ந்தான். வானர அரசனான உன் சிற்றப்பன் ஸுக்ரீவன் மகிழ்ச்சியுடன் என்னிடம்,',
        '0.11': '\'அவர்கள் அனைவரையும் விரைவில் அனுப்பு\' என்று அரசன் சொன்னான்." ததிமுகனின் இந்த மென்மையான சொல்லைக் கேட்டு அங்கதன்,',
        '0.12': 'சொல்வன்மையுடைய அந்த வானர சிரேஷ்டன் அவர்களிடம் சொன்னான்: "படைத்தலைவர்களே, இந்தச் செய்தியை ராமன் கேட்டுவிட்டான் என்று நான் ஐயுறுகிறேன்;',
        '0.13': 'இவன் மகிழ்ச்சியுடன் சொல்வதாலேயே இதை நான் அறிகிறேன். பகைவரை வாட்டுபவர்களே, காரியம் முடிந்த பின் நாம் இங்கு தங்குவது முறையல்ல.',
        '0.14': 'வீரமிக்க வனசாரிகளே, நீங்கள் விருப்பம்போல் தேன் பருகிவிட்டீர்கள்; இனி வானரன் ஸுக்ரீவன் இருக்குமிடத்திற்குச் செல்வதைத் தவிர மீதி என்ன?',
        '0.15': 'சிறந்த வானரர்களான நீங்கள் அனைவரும் சேர்ந்து என்னிடம் என்ன சொல்வீர்களோ அதையே செய்வேன்; கடமையைப் பொறுத்தவரை நான் உங்களுக்குக் கட்டுப்பட்டவன்.',
        '0.16': 'நான் இளவரசனாயினும் உங்களுக்குக் கட்டளையிட உரிமையற்றவன்; காரியத்தை நிறைவேற்றிய உங்களை வலுக்கட்டாயப்படுத்துவது முறையல்ல."',
        '0.17': 'அங்கதன் இவ்வாறு சொன்ன சிறந்த சொல்லைக் கேட்டு மனம் மகிழ்ந்த வனவாசிகள் இவ்வாறு கூறினர்:',
        '0.18': '"வானரரில் சிறந்த அரசே, தலைவனாக இருந்துகொண்டு யார் இப்படிப் பேசுவார்கள்? செல்வச் செருக்கில் மயங்கிய ஒவ்வொருவரும் \'நானே எல்லாம்\' என்று நினைக்கிறான்.',
        '0.19': 'இந்தச் சொல் உனக்கே தகும், வேறு எவருக்கும் அல்ல; உன் பணிவு எதிர்கால நன்மைக்கான உன் தகுதியைக் காட்டுகிறது.',
        '0.20': 'வானர வீரர்களின் நிலையான தலைவனான ஸுக்ரீவன் இருக்குமிடத்திற்குச் செல்ல நாங்கள் அனைவரும் ஆயத்தமாகவும் ஆவலாகவும் இருக்கிறோம்.',
        '0.21': 'வானரரில் சிறந்தவனே, நீ சொல்லாமல் வானரர் எங்கும் ஓர் அடியும் எடுத்து வைக்க முடியாது; இதை உனக்கு உண்மையாகச் சொல்கிறோம்."',
        '0.22': 'அவர்கள் இவ்வாறு சொல்ல, அங்கதன் "நன்று, செல்வோம்" என்று பதிலளித்தான்; அவ்வாறு சொல்லி அந்த மாவலியோர் வானில் எழுந்தனர்.',
        '0.23': 'அவன் எழுந்ததும் அந்தப் படைத்தலைவர்கள் அனைவரும் இயந்திரத்தால் வீசப்பட்ட கற்களைப் போல் வானில் இடைவெளியே இல்லாமல் செய்து அவனைத் தொடர்ந்து எழுந்தனர்.',
        '0.24': 'அங்கதனையும் வானரன் ஹனுமானையும் முன்னிறுத்தி அந்த வேகமிக்க வானரர் திடீரென வானில் தாவி,',
        '0.25': 'காற்றால் தள்ளப்பட்ட மேகங்களைப் போல் பெருமுழக்கமிட்டபடி சென்றனர். அங்கதன் அருகில் வந்ததும் வானர அரசன் ஸுக்ரீவன்',
        '0.26': 'துயரால் வெந்திருந்த தாமரைக்கண்ணன் ராமனிடம் சொன்னான்: "ஆறுதல் கொள், உனக்கு நலம் உண்டாகட்டும்; தேவி காணப்பட்டாள், ஐயமில்லை.',
        '0.27': 'கெடு கடந்த அவர்கள் இல்லையென்றால் இங்கு வரவே முடியாது; அழகிய தோற்றமுடையவனே, அங்கதனின் மகிழ்ச்சியாலும் இதை அறிகிறேன்.',
        '0.28': 'காரியம் கெட்டுப்போயிருந்தால் தாவுவோரில் சிறந்த வலிய கரங்களுடைய இளவரசன் அங்கதன் என்னிடம் வந்திருக்க மாட்டான்;',
        '0.29': 'காரியம் முடிக்காதவர்கள் இவ்வாறு வந்தாலும், அவன் வாடிய முகத்துடனும் குழம்பிக் கலங்கிய மனத்துடனும் வந்திருப்பான்.',
        '0.30': 'ஜனகனின் மகளைக் காணாதிருந்தால், தந்தை பாட்டன் வழி வந்த, முன்னோர்களால் காக்கப்பட்ட என் மதுவனத்தை அவன் அழித்திருக்க மாட்டான்.',
        '0.31': 'நல்விரதமுடைய ராமா, கௌசல்யை நல்ல மகனைப் பெற்றவள்; ஆறுதல் கொள். தேவி காணப்பட்டாள், ஐயமில்லை; அதுவும் ஹனுமானால்தான், வேறு யாராலுமல்ல.',
        '0.32': 'இக்காரியத்தை நிறைவேற்ற ஹனுமானைத் தவிர வேறு யாரும் காரணமாக முடியாது; அறிவாளிகளில் சிறந்தவனே, ஹனுமானிடம் சித்தியும் அறிவும் உள்ளன,',
        '0.33': 'உறுதியும் வீரமும் கல்வியும் நிலைபெற்றுள்ளன. ஜாம்பவான் தலைவனாகவும், வானரத் தலைவன் அங்கதனும் இருந்து,',
        '0.34': 'ஹனுமான் வழிநடத்துபவனாக இருக்குமிடத்தில் வேறு விளைவு இருக்க முடியாது. அளவற்ற வீரமுடையவனே, இப்போது கவலைப்படாதே.',
        '0.35': 'வனவாசிகள் இவ்வாறு செருக்கும் உற்சாகமும் கொண்டு ஒன்றுகூடியிருக்கும்போது, காரியம் கைகூடாவிட்டால் அவர்கள் இப்படி நடந்துகொள்ள மாட்டார்கள்.',
        '0.36': 'வனத்தை அழித்ததாலும் தேனை உண்டதாலும் இதை அறிகிறேன்." அப்போது அவன் வானில் அருகிலேயே கிலகில என்ற ஒலியைக் கேட்டான்;',
        '0.37': 'ஹனுமானின் சாதனையால் பெருமிதம் கொண்டு, முழங்கியபடி கிஷ்கிந்தைக்கு வந்துகொண்டிருந்த வனவாசிகள் தங்கள் வெற்றியை அறிவிப்பது போலிருந்தது.',
        '0.38': 'கபிகளின் அந்த முழக்கத்தைக் கேட்டுக் கபிசிரேஷ்டன் ஸுக்ரீவன் வாலை நீளமாக வளைத்து மனம் மகிழ்ந்தான்.',
        '0.39': 'ராமனைக் காணும் ஆவலுடன் அந்த வானரரும் அங்கதனையும் வானரன் ஹனுமானையும் முன்னிறுத்தி வந்து சேர்ந்தனர்.',
        '0.40': 'அங்கதன் முதலான அந்த வீரர்கள் உவகையும் மகிழ்ச்சியும் நிறைந்து வானர அரசன் மற்றும் ராகவன் அருகில் இறங்கினர்.',
        '0.41': 'வலிய கரங்களுடைய ஹனுமான் தலைவணங்கி, தேவி நியமம் தவறாமலும் எந்தக் குறையுமின்றியும் இருக்கிறாள் என்று ராகவனிடம் தெரிவித்தான்.',
        '0.42': '"தேவியைக் கண்டேன்" என்ற அமுதம் போன்ற சொல்லை ஹனுமானின் வாயிலிருந்து கேட்டு ராமன் லக்ஷ்மணனுடன் மகிழ்ந்தான்.',
        '0.43': 'வாயுமைந்தனைப் பற்றி உறுதியான நம்பிக்கை கொண்டிருந்த மகிழ்ந்த ஸுக்ரீவனை மகிழ்ந்த லக்ஷ்மணன் பெரும் மதிப்புடன் நோக்கினான்.',
        '0.44': 'பகைவீரரைக் கொல்லும் ராகவன் பேரன்பு நிறைந்து, மிகுந்த மதிப்புடன் ஹனுமானை நோக்கினான்.',
        '0.45': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் அறுபத்துநான்காம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sundarakanda-65': {
      verses: {
        '0.0': 'பின்னர் அவர்கள் அழகிய காடுகள் நிறைந்த பிரஸ்ரவண மலைக்குச் சென்று ராமனையும் மாவலியோனான லக்ஷ்மணனையும் தலைவணங்கி வணங்கினர்;',
        '0.1': 'இளவரசனை முன்னிறுத்தி ஸுக்ரீவனையும் வணங்கி, பின்னர் சீதையின் செய்தியைச் சொல்லத் தொடங்கினர்:',
        '0.2': 'ராவணனின் அந்தப்புரத்தில் அவள் சிறைப்பட்டிருப்பது, ராக்ஷஸிகளின் மிரட்டல், ராமனிடம் அவள் கொண்ட அன்பு, அவள் மேற்கொண்ட நியமம்.',
        '0.3': 'வானரர் ராமனின் முன்னிலையில் இவை அனைத்தையும் சொன்னதும், வைதேஹி நலமுடன் இருப்பதைக் கேட்டு ராமன் பதிலாகச் சொன்னான்:',
        '0.4': '"தேவி சீதை எங்கே இருக்கிறாள்? என்னிடம் அவள் மனநிலை எப்படி உள்ளது? வானரர்களே, வைதேஹியைப் பற்றி இவை அனைத்தையும் எனக்குச் சொல்லுங்கள்."',
        '0.5': 'ராமனின் சொல்லைக் கேட்டு ராமன் முன்னிலையிலிருந்த வானரர், சீதையின் செய்தியை நன்கறிந்த ஹனுமானைப் பேசுமாறு தூண்டினர்.',
        '0.6': 'அவர்களின் சொல்லைக் கேட்டு வாயுமைந்தன் ஹனுமான் சீதாதேவி இருக்கும் திசையை நோக்கித் தலைவணங்கி,',
        '0.7': 'சொல்வன்மையுடைய அவன் சீதையை எப்படிக் கண்டான் என்று சொன்னான். தன் ஒளியால் ஒளிர்ந்த அந்தத் தெய்வீகப் பொன்மணியை',
        '0.8': 'ஹனுமான் ராமனிடம் கொடுத்து, பின்னர் கைகூப்பிச் சொன்னான்: "நூறு யோஜனை அகலமான கடலைத் தாண்டி,',
        '0.9': 'ஜானகியான சீதையைக் காணும் ஆவலுடன் தேடிச் சென்றேன். அங்கே தீய ராவணனின் லங்கை எனும் நகரம் உள்ளது;',
        '0.10': 'அது தென்கடலின் தென்கரையில் உள்ளது. அங்கே ராவணனின் அந்தப்புரத்தில் கற்புடைய சீதையைக் கண்டேன்;',
        '0.11': 'ராமா, அந்த அழகி தன் விருப்பங்கள் அனைத்தையும் உன்னிடமே வைத்து உயிர் வாழ்கிறாள். ராக்ஷஸிகளிடையே மீண்டும் மீண்டும் மிரட்டப்படும் அவளைக் கண்டேன்;',
        '0.12': 'இன்பவனத்தில் விகாரமான ராக்ஷஸிகளால் காவல் காக்கப்படுகிறாள். வீரனே, உன்னுடன் இன்பம் அனுபவிக்கத் தகுந்த தேவி துயரம் அனுபவிக்கிறாள்.',
        '0.13': 'ராவணனின் அந்தப்புரத்தில் சிறைப்பட்டு, ராக்ஷஸிகளால் கடுமையாகக் காவல் காக்கப்பட்டு, ஒற்றைச் சடையுடன், துயருற்று உன் நினைவிலேயே மூழ்கியிருக்கிறாள்;',
        '0.14': 'தரையில் படுக்கிறாள், பனிக்காலம் வந்தபோது தாமரைக்கொடி போல் வாடியிருக்கிறாள், ராவணனிடமிருந்து மனதைத் திருப்பி இறக்கத் தீர்மானித்துள்ளாள்.',
        '0.15': 'காகுத்ஸ்தனே, குற்றமற்றவனே, இக்ஷ்வாகு குலப் புகழை மெல்லப் பாடியபடி, உன்னிடமே மனம் வைத்த தேவியை நான் எப்படியோ கண்டுபிடித்தேன்.',
        '0.16': 'ஆண்களில் புலியே, அப்போது நான் மெல்ல அவள் நம்பிக்கையைப் பெற்றேன்; பின்னர் தேவியுடன் பேசி எல்லா விஷயத்தையும் தெளிவுபடுத்தினேன்.',
        '0.17': 'ராமன்-ஸுக்ரீவன் நட்பைக் கேட்டு அவள் மகிழ்ந்தாள். அவள் நடத்தை கட்டுப்பாடானது, அவள் பக்தி எப்போதும் உன்னிடமே.',
        '0.18': 'பெருமைக்குரியவனே, ஆண்களில் சிறந்தவனே, இவ்வாறு உன்மீதுள்ள பக்தியால் கடுந்தவத்தில் ஈடுபட்டிருக்கும் ஜனகனின் மகளை நான் கண்டேன்.',
        '0.19': 'பேரறிஞனான ராகவா, சித்திரகூடத்தில் உன் முன்னிலையில் காகத்தைப் பற்றி நடந்ததை அவள் எனக்கு அடையாளமாகச் சொன்னாள்.',
        '0.20': '\'வாயுமைந்தனே, நீ கண்டவை அனைத்தையும் முழுமையாக ராமனிடம் மீண்டும் தெரிவி\' என்று ஜானகி என்னிடம் சொன்னாள்.',
        '0.21': '\'இதைக் கவனமாகப் பாதுகாத்து அவனிடம் கொடுக்க வேண்டும்\' என்றாள். ஸுக்ரீவன் கேட்டுக்கொண்டிருக்க அவள் சொற்களை இப்போது சொல்கிறேன்:',
        '0.22': '\'இந்த ஒளிமிக்க சூடாமணியை உனக்காகக் கவனமாகப் பாதுகாத்து வைத்தேன்; மனோசிலைத் திலகத்தை நினைவுகூர்\' என்று சொன்னாள்.',
        '0.23': '\'நீரில் பிறந்த இந்த ஒளிமிக்க மணியை உனக்குத் திருப்பி அனுப்பியுள்ளேன்; குற்றமற்றவனே, துன்பத்தில் இதைக் கண்டு உன்னைக் கண்டது போல் மகிழ்ந்திருந்தேன்.',
        '0.24': 'தசரதன் மைந்தனே, ஒரு மாதம் வரை உயிரைத் தாங்கியிருப்பேன்; ராக்ஷஸர் வசப்பட்ட நான் மாதத்திற்குப் பின் உயிர் வாழமாட்டேன்.\'',
        '0.25': 'மெலிந்த உடலுடைய, அறவழி நடக்கும், ராவணனின் அந்தப்புரத்தில் சிறைப்பட்ட, மான்போல் விரிந்த கண்களுடைய சீதை என்னிடம் இவ்வாறு சொன்னாள்.',
        '0.26': 'ராகவா, நடந்தபடியே அனைத்தையும் சொல்லிவிட்டேன். எல்லா வகையிலும் கடல்நீரைக் கடக்கும் வழியை ஏற்பாடு செய்வோம்."',
        '0.27': 'அந்த இரு இளவரசர்களும் ஆறுதல் அடைந்ததை அறிந்து, அந்த அடையாளத்தை ராகவனிடம் ஒப்படைத்து, வாயுமைந்தன் தேவி சொன்னவை அனைத்தையும் வரிசைப்படி முழுமையாகத் தெரிவித்தான்.',
        '0.28': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் அறுபத்தைந்தாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sundarakanda-66': {
      verses: {
        '0.0': 'ஹனுமான் இவ்வாறு சொன்னதும் தசரதன் மைந்தன் ராமன் அந்த மணியை நெஞ்சோடு அணைத்து லக்ஷ்மணனுடன் அழுதான்.',
        '0.1': 'அந்தச் சிறந்த மணியைக் கண்டு துயரால் மெலிந்த ராகவன் கண்ணீர் நிறைந்த கண்களுடன் ஸுக்ரீவனிடம் இவ்வாறு சொன்னான்:',
        '0.2': '"பாசமுள்ள பசு கன்றின் மீதுள்ள அன்பால் பால் சுரப்பது போல், இந்தச் சிறந்த மணியைக் கண்டு என் இதயமும் உருகுகிறது.',
        '0.3': 'இந்த அரிய மணியை என் மாமனார் வைதேஹிக்குக் கொடுத்தார்; திருமணத்தின்போது அவள் தலையில் கட்டப்பட்டபோது இது மேலும் ஒளிர்ந்தது.',
        '0.4': 'நீரில் பிறந்த, சிறந்தோரால் போற்றப்பட்ட இந்த மணியை வேள்வியில் பெரிதும் மகிழ்ந்த அறிவுடைய இந்திரன் கொடுத்தான்.',
        '0.5': 'நண்பனே, இந்தச் சிறந்த மணியைக் கண்டு இன்று என் தந்தையையும் விதேக அரசனான பிரபுவையும் கண்டது போலிருக்கிறது.',
        '0.6': 'இந்த மணி என் அன்புக்குரியவளின் தலையில் ஒளிர்ந்தது; இன்று இதைக் கண்டு அவளே கிடைத்தது போல் உணர்கிறேன்.',
        '0.7': 'வைதேஹியான சீதை என்ன சொன்னாள்? நண்பனே, இறக்கும் நிலையிலுள்ளவன் மேல் நீர் தெளிப்பது போல் அவள் சொல்லெனும் நீரைத் தெளித்தபடி மீண்டும் மீண்டும் சொல்.',
        '0.8': 'ஸௌமித்ரியே, வைதேஹி வராமல் நீரில் பிறந்த இந்த மணியை மட்டும் காண்பதைவிடப் பெரிய துயரம் என்ன இருக்கிறது?',
        '0.9': 'வைதேஹி ஒரு மாதம் உயிர் தாங்கினால் அதுவே நீண்ட காலம்; வீரனே, அந்தக் கருவிழியாள் இல்லாமல் நான் ஒரு கணமும் வாழ முடியாது.',
        '0.10': 'என் அன்புக்குரியவள் காணப்பட்ட அந்த இடத்திற்கு என்னையும் அழைத்துச் செல்; அவள் செய்தி கிடைத்த பின் நான் ஒரு கணமும் இங்கு இருக்க முடியாது.',
        '0.11': 'மிகவும் அஞ்சும் இயல்புடைய, கற்புடைய என் அழகி இப்போது பயங்கரமான கொடிய ராக்ஷஸர்களிடையே எப்படி இருக்கிறாள்?',
        '0.12': 'இருளிலிருந்து விடுபட்ட கூதிர்கால நிலவு மேகங்களால் மறைக்கப்பட்டது போல், அவள் முகம் இப்போது நிச்சயமாக ஒளியிழந்திருக்கும்.',
        '0.13': 'ஹனுமானே, சீதை என்ன சொன்னாள்? எனக்கு உள்ளபடி சொல். நோயாளி மருந்தால் வாழ்வது போல் நான் இதனாலேயே வாழ்வேன்.',
        '0.14': 'இனியவளும் இனிமையாகப் பேசுபவளும் என்னைப் பிரிந்தவளுமான என் அழகி என்ன சொன்னாள்? ஹனுமானே, சொல்: துயரத்திலிருந்து பெருந்துயரத்தில் வீழ்ந்து ஜானகி எப்படி உயிர் வாழ்கிறாள்?"',
        '0.15': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் அறுபத்தாறாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sundarakanda-67': {
      verses: {
        '0.0': 'மகாத்மா ராகவன் இவ்வாறு கேட்க, ஹனுமான் சீதை சொன்னவை அனைத்தையும் ராகவனிடம் தெரிவித்தான்.',
        '0.1': '"ஆண்களில் சிறந்தவனே, தேவி ஜானகி சித்திரகூடத்தில் முன்பு நடந்த நிகழ்ச்சியை அடையாளமாக உள்ளபடியே இவ்வாறு சொன்னாள்:',
        '0.2': 'உன்னுடன் இன்பமாக உறங்கிய ஜானகி முதலில் விழித்தாள்; ஒரு காகம் திடீரெனப் பாய்ந்து அவள் மார்பைக் கீறியது.',
        '0.3': 'பின்னர் பரதனின் அண்ணனே, நீ முறைப்படி தேவியின் மடியில் உறங்கினாய்; அந்தப் பறவை மீண்டும் தேவியைத் துன்புறுத்தியதாம்.',
        '0.4': 'மீண்டும் வந்து அது அவளைக் கடுமையாகக் கீறியதாம்; அப்போது அவள் இரத்தத்தால் நனைந்து நீ விழித்தாய்.',
        '0.5': 'இவ்வாறு அந்தக் காகத்தால் இடைவிடாமல் துன்புறுத்தப்பட்ட தேவி, பகைவரை வாட்டுபவனே, இன்பமாக உறங்கிய உன்னை எழுப்பினாளாம்.',
        '0.6': 'வலிய கரங்களுடையவனே, மார்பில் காயமடைந்த அவளைக் கண்டு நீ நச்சுப்பாம்பு போல் சினந்து இவ்வாறு சொன்னாய்:',
        '0.7': '\'அஞ்சுபவளே, நகநுனிகளால் உன் மார்பைக் கீறியவன் யார்? சினங்கொண்ட ஐந்துதலை நாகத்துடன் விளையாடுபவன் யார்?\'',
        '0.8': 'சுற்றிலும் பார்த்தபோது நீ திடீரென, இரத்தம் தோய்ந்த கூர்மையான நகங்களுடன் அவள் முன்னே அமர்ந்திருந்த அந்தக் காகத்தைக் கண்டாய்.',
        '0.9': 'பறவைகளில் சிறந்த அந்தக் காகம் இந்திரனின் மகனாம்; பூமியில் விரைந்து திரிவது, வேகத்தில் காற்றுக்கு நிகரானது.',
        '0.10': 'அப்போது வலிய கரங்களுடையவனே, அறிவாளிகளில் சிறந்தவனே, சினத்தால் கண்களை உருட்டியபடி நீ அந்தக் காகத்தைக் குறித்துக் கடுமையான முடிவெடுத்தாய்.',
        '0.11': 'தர்ப்பைப் படுக்கையிலிருந்து ஒரு தர்ப்பையை எடுத்து பிரம்மாஸ்திரத்தால் மந்திரித்தாய்; அது ஊழித்தீ போல் எரிந்து பறவையை நோக்கிக் கொழுந்துவிட்டது.',
        '0.12': 'எரியும் அந்தத் தர்ப்பையை நீ காகத்தை நோக்கி எறிந்தாய்; எரியும் அந்தத் தர்ப்பை காகத்தைத் துரத்தியது.',
        '0.13': 'அஞ்சிய எல்லாத் தேவர்களாலும் கைவிடப்பட்ட அந்தக் காகம் மூவுலகங்களையும் சுற்றியும் காப்பவனைக் காணவில்லை.',
        '0.14': 'பகைவரை அடக்குபவனே, அது மீண்டும் அங்கு உன்னிடமே வந்தது; அடைக்கலம் தருபவனான நீ, தரையில் விழுந்து சரணடைந்த அதை,',
        '0.15': 'காகுத்ஸ்தனே, கொல்லத்தக்கதாயினும் கருணையால் காப்பாற்றினாய். ஆனால் ராகவா, அஸ்திரத்தை வீணாக்க முடியாததால்,',
        '0.16': 'நீ அந்தக் காகத்தின் வலக்கண்ணை அழித்தாய். ராமா, பின்னர் அது உனக்கும் அரசன் தசரதனுக்கும் வணக்கம் செலுத்தி,',
        '0.17': 'விடுவிக்கப்பட்டுத் தன் இருப்பிடத்திற்குத் திரும்பியது. இவ்வாறு அஸ்திரம் அறிந்தோரில் சிறந்தவனும் வலிமையும் நல்லொழுக்கமும் உடையவனுமான நீ,',
        '0.18': 'ராகவா, ராக்ஷஸர்கள் மீது ஏன் அஸ்திரத்தைப் பிரயோகிக்கவில்லை? தானவரோ, கந்தர்வரோ, அசுரரோ, மருத்கணங்களோ,',
        '0.19': 'ராமா, போரில் உன்னை எதிர்த்து நிற்க வல்லவர்கள் அல்ல. வீரனான உனக்கு என்மேல் சிறிதேனும் அக்கறை இருந்தால்,',
        '0.20': 'நன்கு கூர்மையான அம்புகளால் போரில் ராவணனை விரைவில் கொல். அல்லது அண்ணனின் ஆணை பெற்றுப் பகைவரை வாட்டும் லக்ஷ்மணனாவது —',
        '0.21': 'அந்த ஆண்களில் சிறந்த ராகவன் ஏன் என்னைக் காக்கவில்லை? அந்த இரு ஆண்புலிகளும் வல்லவர்கள், காற்றுக்கும் நெருப்புக்கும் நிகரான ஒளியுடையவர்கள்,',
        '0.22': 'தேவர்களுக்கும் வெல்லமுடியாதவர்கள்; ஏன் என்னைப் புறக்கணிக்கிறார்கள்? என்னுடைய ஏதோ பெரிய பாவம் இருக்க வேண்டும், ஐயமில்லை;',
        '0.23': 'ஏனெனில் வல்லவர்களான அந்த இரு பகைவரை வாட்டுவோரும் சேர்ந்திருந்தும் என்னைக் காக்கவில்லை.\' வைதேஹியின் இரக்கமான, அழகாகப் பேசப்பட்ட சொற்களைக் கேட்டு,',
        '0.24': 'நான் அந்த மேன்மையானவளிடம் மீண்டும் இவ்வாறு சொன்னேன்: \'தேவியே, உன்னைப் பற்றிய துயரத்தால் ராமன் அனைத்திலிருந்தும் விலகியிருக்கிறான்; இதை உண்மையின் மீது ஆணையிட்டுச் சொல்கிறேன்.',
        '0.25': 'ராமன் துயரில் ஆழ்ந்திருப்பதால் லக்ஷ்மணனும் வருந்துகிறான். எப்படியோ நீ காணப்பட்டாய்; இது வருந்தும் நேரமல்ல.',
        '0.26': 'பெண்மணியே, இந்தக் கணத்திலேயே உன் துயரங்களின் முடிவைக் காண்பாய். ஆண்களில் புலிகளும் பகைவரை வாட்டுவோருமான அந்த இரு இளவரசர்கள்,',
        '0.27': 'உன்னைக் காணும் ஆர்வத்தால் லங்கையைச் சாம்பலாக்குவார்கள்; போரில் கொடியவனான ராவணனை உறவினருடன் கொன்று,',
        '0.28': 'அழகியே, ராகவன் நிச்சயமாக உன்னைத் தன் நகருக்கு அழைத்துச் செல்வான். குற்றமற்றவளே, ராமன் அடையாளம் கண்டுகொள்ளக்கூடிய எந்த அடையாளம் உள்ளதோ,',
        '0.29': 'அவனுக்கு மகிழ்ச்சி தரக்கூடியதை நீ தர வேண்டும்.\' அவள் எல்லாத் திசைகளையும் பார்த்து, சடையில் கட்டியிருந்த சிறந்த அணிகலனை',
        '0.30': 'ஆடையிலிருந்து அவிழ்த்து இந்த மணியை என்னிடம் கொடுத்தாள், மாவலியோனே. ரகுகுலத்தோருக்கு இனியவனே, உனக்காக இரு கைகளாலும் அந்த மணியைப் பெற்று,',
        '0.31': 'அவளைத் தலைவணங்கி வணங்கி நான் திரும்பி வர விரைந்தேன். செல்ல ஆவலுற்ற என்னைக் கண்டு அந்த அழகி,',
        '0.32': 'நான் வளர்வதைக் கண்டு ஜனகனின் மகள் கண்ணீர் நிறைந்த முகத்துடன், துயருற்று, தழுதழுத்த குரலில் என்னிடம் சொன்னாள்;',
        '0.33': 'நான் தாவப்போவதால் பதறி, துயரப் பெருக்கால் தாக்குண்ட சீதை அப்போது என்னிடம் சொன்னாள்: \'மாகபியே, நீ பாக்கியசாலி,',
        '0.34': 'ஏனெனில் நீ வலிய கரங்களுடைய தாமரைக்கண்ணன் ராமனையும், என் புகழ்மிக்க மைத்துனன் வலிய கரங்களுடைய லக்ஷ்மணனையும் காண்பாய்.\'',
        '0.35': 'சீதை இவ்வாறு சொல்ல நான் மைதிலியிடம் சொன்னேன்: \'தேவியே, ஜனகனின் மகளே, விரைவில் என் முதுகில் ஏறு;',
        '0.36': 'பெருமைக்குரியவளே, கருவிழியாளே, இன்றே உனக்கு ஸுக்ரீவன், லக்ஷ்மணனுடன் உன் கணவன் ராகவனைக் காட்டுவேன்.\'',
        '0.37': 'அப்போது தேவி என்னிடம் சொன்னாள்: \'மாகபியே, வானரத் தலைவனே, நான் சொந்த விருப்பத்தால் உன் முதுகில் ஏறுவது அறமல்ல.',
        '0.38': 'வீரனே, முன்பு ராக்ஷஸன் என் உடலைத் தொட்டது — விதியால் வாட்டப்பட்ட நான் அப்போது என்ன செய்ய முடியும்?',
        '0.39': 'கபிகளில் புலியே, அந்த இரு அரசகுமாரர்களும் இருக்குமிடத்திற்கு நீ செல்.\' இவ்வாறு சொல்லி அவள் மேலும் செய்தி சொல்லத் தொடங்கினாள்:',
        '0.40': '\'ஹனுமானே, சிங்கம் போன்ற அந்த ராம லக்ஷ்மணர் இருவருக்கும், அமைச்சர்களுடன் ஸுக்ரீவனுக்கும், அனைவருக்கும் என் நலத்தைத் தெரிவி.',
        '0.41': 'இந்தத் துயரக் கடலின் சிறையிலிருந்து வலிய கரங்களுடைய ராகவன் என்னை எப்படி மீட்க வேண்டுமோ அதை நீ அவர்களிடம் சொல்ல வேண்டும்.',
        '0.42': 'ராமனிடம் சென்றதும் என் இந்தக் கடுமையான துயரப் பெருக்கையும் இந்த ராக்ஷஸர்களின் மிரட்டல்களையும் சொல். வானர வீரனே, உன் பயணம் மங்கலமாகட்டும்.\'',
        '0.43': 'அரசே, உன் மேன்மையான, அடக்கமுடைய சீதை துயரத்துடன் உனக்குச் சொன்ன சொற்கள் இவை. சொல்லப்பட்டதை உள்ளபடி அறிந்து, சீதை முழுமையாக நலமுடன் இருக்கிறாள் என்று நம்பு."',
        '0.44': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் அறுபத்தேழாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
    'sundarakanda-68': {
      verses: {
        '0.0': '"ஆண்களில் புலியே, பின்னர் உன்மீதுள்ள அன்பாலும் நட்பாலும் தேவி என்னைக் கௌரவித்து, பதற்றத்துடன் மீண்டும் பதிலாகச் சொன்னாள்:',
        '0.1': '\'தசரதன் மைந்தன் ராமன் போரில் ராவணனைக் கொன்று விரைவில் என்னை அடையும்படி நீ அவனிடம் பலவாறாகச் சொல்ல வேண்டும்.',
        '0.2': 'அல்லது வீரனே, பகைவரை அடக்குபவனே, உனக்குச் சரியெனப்பட்டால் ஏதாவது மறைவான இடத்தில் ஒரு நாள் தங்கி, ஓய்வெடுத்து நாளை செல்.',
        '0.3': 'வானரனே, உன் அருகாமையால் பாக்கியம் குறைந்த எனக்கும் இந்தத் துயரத்தின் விளைவிலிருந்து ஒரு கணமேனும் விடுதலை கிடைக்கலாம்.',
        '0.4': 'வீரனான நீ சென்றபின் மீண்டும் திரும்பி வரும்வரை என் உயிரைப் பற்றியே ஐயம்; இதில் சந்தேகமில்லை.',
        '0.5': 'துயரத்தின் மேல் துயரத்தால் நொந்த, கதியற்ற, துன்பத்தையே பங்காகப் பெற்ற என்னை, உன்னைக் காணாத துயரம் மேலும் வாட்டும்.',
        '0.6': 'வீரனே, வானரத் தலைவனே, உன் துணைவர்களான வானரர்-கரடிகள் பற்றி இந்தப் பெரும் ஐயம் என் முன் நிற்பது போலிருக்கிறது:',
        '0.7': 'அந்த வானர-கரடிச் சேனைகளோ, மனிதரில் சிறந்தவனின் அந்த இரு மைந்தர்களோ கடக்கமுடியாத இந்தப் பெருங்கடலை எப்படிக் கடப்பார்கள்?',
        '0.8': 'இந்தக் கடலைத் தாண்டும் ஆற்றல் மூவருக்கு மட்டுமே உண்டு: வினதையின் மகன் கருடனுக்கு, வாயுவுக்கு, குற்றமற்றவனான உனக்கு.',
        '0.9': 'ஆகவே வீரனே, இவ்வாறு கடினமான இக்காரியத்தில் நீ என்ன தீர்வைக் காண்கிறாய்? காரியம் அறிந்தோரில் சிறந்தவனே, சொல்.',
        '0.10': 'பகைவீரரைக் கொல்பவனே, இக்காரியத்தை நிறைவேற்ற நீ ஒருவனே போதும் என்பது உண்மைதான்; உன் வலிமையின் எழுச்சி புகழ் தருவது.',
        '0.11': 'ஆனால் ராமன் முழுச் சேனைகளுடன் போரில் ராவணனைக் கொன்று வெற்றியாளனாக என்னைத் தன் நகருக்கு அழைத்துச் சென்றால் அதுவே அவனுக்குப் புகழ் தரும்.',
        '0.12': 'அந்த வீரனுக்கு அஞ்சியே ராக்ஷஸன் என்னை வனத்திலிருந்து வஞ்சகமாகக் கவர்ந்தது போல் ராகவன் என்னை மீட்பது தகாது.',
        '0.13': 'ஆனால் பகைச்சேனையை நசுக்கும் காகுத்ஸ்தன் தன் சேனைகளால் லங்கையை நிரப்பி என்னை அழைத்துச் சென்றால் அதுவே அவனுக்குத் தகும்.',
        '0.14': 'ஆகவே போர்வீரனான அந்த மகாத்மாவின் வீரத்திற்கு ஏற்றபடி நடக்கும்படி நீ ஏற்பாடு செய்.\'',
        '0.15': 'பொருள் நிறைந்த, பணிவான, காரணம் பொருந்திய அவள் சொல்லைக் கேட்டு நான் மீதிப் பதிலைச் சொன்னேன்:',
        '0.16': '\'தேவியே, வானர-கரடிச் சேனைகளின் தலைவனும் தாவுவோரில் சிறந்தவனும் வலிமை நிறைந்தவனுமான ஸுக்ரீவன் உனக்காக உறுதியான தீர்மானம் கொண்டுள்ளான்.',
        '0.17': 'அவன் ஆணைக்குக் கீழ் வீரமும் வலிமையும் பெருவலியும் மனவேகமும் உடைய வானரர் இருக்கிறார்கள்.',
        '0.18': 'அவர்களின் செலவு மேலேயோ கீழேயோ குறுக்கேயோ எங்கும் தடைபடாது; அளவற்ற ஒளியுடைய அவர்கள் பெரும் செயல்களில் ஒருபோதும் சோர்வதில்லை.',
        '0.19': 'பெருமைமிக்க, வலிமையுடைய அந்த வானரர் காற்றின் வழியைப் பின்பற்றிப் பலமுறை பூமியை வலம் வந்துள்ளனர்.',
        '0.20': 'அங்கே என்னைவிடச் சிறந்தவர்களும் எனக்கு நிகரானவர்களுமான வனவாசிகள் இருக்கிறார்கள்; ஸுக்ரீவனிடம் என்னைவிடத் தாழ்ந்தவர் ஒருவருமில்லை.',
        '0.21': 'நானே இங்கு வந்திருக்கும்போது அந்த மாவலியோரைப் பற்றிச் சொல்லவும் வேண்டுமோ! சிறந்தவர்கள் தூதர்களாக அனுப்பப்படுவதில்லை, சாதாரணமானவர்களே அனுப்பப்படுகின்றனர்.',
        '0.22': 'ஆகவே தேவியே, வருந்தாதே; உன் துயரம் நீங்கட்டும். ஒரே தாவலில் வானரப் படைத்தலைவர்கள் லங்கையை அடைவார்கள்.',
        '0.23': 'பெருமைக்குரியவளே, உதித்த சூரிய சந்திரர் போன்ற அந்த இரு மனிதருள் சிங்கங்களும் என் முதுகில் அமர்ந்து உன்னிடம் வருவார்கள்.',
        '0.24': 'பகைவரைக் கொல்லும் சிங்கம் போன்ற ராகவனையும் வில்லேந்திய லக்ஷ்மணனையும் லங்கையின் வாயிலுக்கு வந்திருப்பதை நீ விரைவில் காண்பாய்.',
        '0.25': 'நகங்களையும் கோரைப்பற்களையும் ஆயுதமாகக் கொண்ட, சிங்கம்-புலிகளின் வீரமுடைய, யானைத் தலைவர்கள் போன்ற வீர வானரர் ஒன்றுகூடியிருப்பதை நீ விரைவில் காண்பாய்.',
        '0.26': 'லங்கையின் மலய மலைச் சரிவுகளில் முழங்கும், மலைகளையும் மேகங்களையும் போன்ற வானரத் தலைவர்களின் முழக்கத்தை நீ விரைவில் கேட்பாய்.',
        '0.27': 'வனவாசம் முடிந்த பகைவரை அடக்கும் ராகவன் உன்னுடன் அயோத்தியில் முடிசூட்டப்பட்டிருப்பதை நீ விரைவில் காண்பாய்.\'',
        '0.28': 'அப்போது நான் சொன்ன மங்கலமான, இனிய சொற்களால் ஆறுதல் பெற்ற, தளர்வின்றிப் பேசும் மைதிலி, உன்னைப் பற்றிய மிகுந்த துயரத்தால் பெரிதும் வாடியிருந்தும், அமைதி அடைந்தாள்."',
        '0.29': 'இவ்வாறு ஆர்ஷமான ஆதிகாவியமான ஸ்ரீமத் வால்மீகி ராமாயணத்தின் சுந்தரகாண்டத்தில் அறுபத்தெட்டாம் சர்க்கம் நிறைவுற்றது.',
      },
    },
  },
};
